/* Shared reversible Persian-English dictionary for all PLANET UI pages. */
(function(root){'use strict';const pairs=[["فرد انتخاب‌شده · عمل فعلی","Selected individual · current action"],["امتیاز شناخت دیجیتال","Digital cognition index"],["انرژی / سلامت","Energy / health"],["بازخورد آخرین تصمیم","Last-decision feedback"],["حافظهٔ تجربه","Experience memory"],["تعداد تصمیم‌ها","Decision count"],["نمونه‌های زندهٔ مشاهده‌شده","Living individuals observed"],["برای بررسی تصمیم‌ها روی یک موجود در تصویر ضربه بزن.","Tap an organism in the scene to inspect its decisions."],["شاخص دیجیتال","digital index"],["بازخورد یادگیری","learning feedback"],["هنوز تجربهٔ کافی ندارد","not enough experience yet"],["نمونه‌های زنده","living samples"],["شناخت دیجیتال","digital cognition"],["عمل رایج فعلی","Most common current action"],["یادگیری و حافظه","Learning and memory"],["همکاری اجتماعی","Social cooperation"],["شاخص شناخت دیجیتال","Digital cognition index"],["آگاهی واقعی","real consciousness"],["یک روز مدل برابر با ۲۴۰ ثانیهٔ شبیه‌سازی است و یک سال مدل ۳۶۵٫۲۵۶ روز دارد. کنترل سرعت، چرخش زمین و مدارها و شمارنده‌های روز/سال را هم‌زمان شتاب می‌دهد. این مقیاس برای مشاهده است، نه زمان واقعی.","One model day equals 240 simulation seconds and one model year equals 365.256 days. The speed control accelerates Earth rotation, orbits and day/year counters together. This scale is for viewing, not real time."],["ژنوم‌های دیجیتال کوتاه‌اند و از جدول کد ژنتیکی استاندارد استفاده می‌کنند؛ نگاشت صفات، پروتئین‌ها و زیستگاه یک تقریب آموزشی است، نه بازسازی مولکولی موجودات واقعی.","The digital genomes are short and use the standard genetic code table; trait, protein and habitat mappings are educational approximations, not molecular reconstructions of real organisms."],["فهرست گونه‌ها","Species registry"],["سن زمین در مدل","Model age of Earth"],["زمان سپری‌شده از آغاز","Elapsed time since start"],["مدل DNA","Digital DNA model"],["مدل تکامل","Evolution model"],["گیاهان بلند و درختان نخستین","Tall plants and early trees"],["تنوع بیشتر آبزیان و ماهی‌ها","Diversifying aquatic life and fish"],["خزندگان نخستین","Early reptiles"],["جانوران بزرگ‌تر و اکوسیستم‌های پیچیده","Larger animals and complex ecosystems"],["فرم‌های گیاهی بلندتر و شبیه درخت روی خشکی نمایش داده می‌شوند.","Taller tree-like forms appear on land."],["فرم‌های کشیده‌تر و شناگر در محیط آبی نمایش داده می‌شوند.","Elongated swimming forms appear in aquatic habitats."],["فرم‌های خشکی‌زیِ کشیده‌تر با دُم نمادین نمایش داده می‌شوند.","Elongated land forms with illustrative tails appear."],["اندازهٔ دیداری جانداران با صفات ژنومی، رشد و مرحلهٔ زمانی مدل تغییر می‌کند.","Organism scale varies with genomic traits, growth and model time."],["دربارهٔ پروژه","About this project"],["سازندهٔ پروژه","Project creator"],["این پروژه یک شبیه‌ساز آموزشی مستقل است که برای نمایش مفاهیم سیاره‌شناسی و تکامل دیجیتال ساخته شده است.","An independent educational simulator for exploring planetary science and digital evolution."],["مدل آموزشی است؛ نه شبیه‌سازی علمیِ اعتبارسنجی‌شده یا بازسازی ژنوم موجودات واقعی.","This is an educational model, not a validated scientific simulation or reconstruction of real organisms."],["مخزن و گزارش مشکلات در GitHub","Source code and issue reports on GitHub"],["درآمده از ژنوم دیجیتال","Derived from digital genome"],["نیا:","Ancestor:"],["نمونهٔ آزمایشگاهی","Lab specimen"],["در ادامهٔ خط زمان","Later in timeline"],["حاضر در مدل","Present in model"],["منقرض‌شده در مدل","Extinct in model"],["زیستگاه:","Habitat:"],["جمعیت:","Population:"],["سوخت‌وساز:","Metabolism:"],["حرکت:","Motility:"],["حفاظت:","Protection:"],["بی‌هوازی","anaerobic"],["تخمیری","fermentative"],["شیمی‌پرور","chemosynthetic"],["نورپرور","photosynthetic"],["روزهای سپری‌شده","Elapsed days"],["سال‌های سپری‌شده","Elapsed years"],["روز مدل","model days"],["سال زمینی مدل","model Earth years"],["زمان با سرعت شبیه‌سازی جلو می‌رود؛ مکث، شمارنده را متوقف می‌کند.","Simulation time advances at the selected speed; pause stops the counter."],["سرعت زمان شبیه‌سازی","Simulation time speed"],["فهرست موجودات ایجادشده","Generated organism catalog"],["گونه‌های پدیدآمده در این اجرای تکامل همراه با ژنوم، نسل، زیستگاه و وضعیت بقا در اینجا ثبت می‌شوند.","Species generated in this evolution run are listed here with their genome, generation, habitat and survival status."],["ساخت نمونهٔ تصادفی آزمایشگاهی","Create random lab specimen"],["بستن فهرست","Close catalog"],["نمونهٔ آزمایشگاهی به‌صورت دستی ساخته می‌شود و شاهدی بر پیدایش طبیعی حیات نیست.","Lab specimens are created manually and are not evidence of natural abiogenesis."],["محیط زیست موجود","Organism habitat"],["نمای زندهٔ یک اکوسیستم محاسباتی","Live digital ecosystem"],["نمای شبیه‌سازی‌شدهٔ زیستگاه","Simulated habitat view"],["پروتئین ترجمه‌شده","Translated protein"],["جمعیت مدل","Model population"],["نسل","Generation"],["سازگاری محیطی","Environmental fitness"],["توالی DNA از A/C/G/T و جدول کد ژنتیکی استاندارد استفاده می‌کند؛ صفات و محیط، مدل دیجیتال آموزشی هستند، نه یک موجود زیستی واقعی.","The DNA sequence uses A/C/G/T and the standard genetic code; traits and habitat are an educational digital model, not a real organism."],["ورود به زیستگاه","Enter habitat"],["یک روز مدل","one model day"],["روزهای شبیه‌سازی","Simulation days"],["سال‌های شبیه‌سازی","Simulation years"],["نوار تکامل","Evolution timeline"],["جابه‌جایی زمانی تکامل","Evolution timeline"],["از ابتدای تاریخ زمین","Beginning of Earth history"],["اکنون","Present"],["زمان زمین‌شناختی","Geological time"],["زیست‌کرهٔ نزدیک به امروز","Near-modern biosphere"],["زمین آغازین · بدون حیات شناخته‌شده","Early Earth · no known life"],["شیمی پیش‌زیستی · گذار نامطمئن به حیات","Prebiotic chemistry · uncertain transition to life"],["میکروب‌های تک‌سلولی اولیه","Early single-celled microbes"],["میکروب‌های فتوسنتزکننده و تغییر چرخهٔ کربن","Photosynthetic microbes and changing carbon cycles"],["افزایش اکسیژن جو","Atmospheric oxygenation"],["سلول‌های پیچیده‌تر و همزیستی","More complex cells and symbiosis"],["زیست دریایی چندسلولی","Multicellular marine ecosystems"],["پیدایش پوشش گیاهی خشکی","Plants colonize land"],["اکوسیستم‌های خشکی پیچیده‌تر","More complex terrestrial ecosystems"],["ورود به محیط زندگی","Enter habitat"],["روز","Day"],["سال","Year"],["آزمایشگاه جهان‌های زنده","Living Worlds Lab"],["شبیه‌سازی فعال · روز","Simulation running · Day"],["شبیه‌سازی فعال · شب","Simulation running · Night"],["شبیه‌سازی فعال","Simulation running"],["شبیه‌سازی متوقف‌شده","Simulation paused"],["مکث‌شده","Paused"],["راهنمای آزمایشگاه Planet","Planet Lab Guide"],["نمای نزدیک نشانه‌های حیات فعال شد.","Life zoom activated."],["به نمای قبلی سیاره برگشتی.","Returned to the previous planet view."],["زاویهٔ دید بازنشانی شد.","View reset."],["مدارها روشن شدند","Orbits enabled"],["مدارها خاموش شدند","Orbits disabled"],["زمان متوقف شد","Time paused"],["زمان ادامه یافت","Time resumed"],["نمای منظومهٔ شمسی","Solar system view"],["نمای نزدیک زمین","Earth close-up"],["نمای منظومه","System view"],["بازنشانی زاویهٔ دید","Reset view"],["زوم روی حیات","Zoom to life"],["بازگشت به نمای زمین","Return to Earth view"],["جهانی آبی با اقیانوس‌ها، ابرهای پویا و جو محافظ؛ یک مدل زنده از شرایط زمین.","A blue world of oceans, dynamic clouds and a protective atmosphere—a live model of Earth-like conditions."],["شش سیاره با دوره‌های مداری متفاوت به دور خورشید؛ فاصله و اندازه برای مشاهده، مقیاس‌گذاری شده‌اند.","Six planets orbit the Sun at different periods. Distances and sizes are scaled for visibility."],["داشبورد سیاره","Planet Dashboard"],["وضعیت محیطی زمین","Earth Environment"],["پایدار","Stable"],["میانگین دما","Average Temperature"],["در محدودهٔ مرجع","Within reference range"],["فشار سطح دریا","Sea-level Pressure"],["استاندارد زمین","Earth standard"],["پوشش ابر","Cloud Cover"],["در حال تغییر","Changing"],["آب مایع سطحی","Surface Liquid Water"],["اقیانوس‌ها و دریاها","Oceans and Seas"],["ترکیب مدل‌شدهٔ جو","Modelled Atmospheric Composition"],["مقادیر جو نزدیک به هوای خشک زمین‌اند؛ بخار آب متغیر است. این پنل داده‌های مدل را نشان می‌دهد، نه اندازه‌گیری زنده از زمین واقعی.","Atmospheric values approximate dry Earth air; water vapour varies. This panel shows model data, not live measurements from Earth."],["ابر: بافت رویه‌ای","Clouds: procedural texture"],["زمان و حرکت","Time and Motion"],["نمای زمین","Earth View"],["منظومه","Solar System"],["مکث","Pause"],["ادامه","Resume"],["سرعت گردش مداری","Orbital Speed"],["واقعی ×1","Realistic ×1"],["شتاب‌داده‌شده","accelerated"],["چرخهٔ محلی ثابت است: ۲ دقیقه روز + ۲ دقیقه شب. سرعت مدار جداگانه تنظیم می‌شود تا حرکت منظومه قابل مشاهده باشد. برای نسبت زمانی نزدیک‌تر به واقعیت، سرعت مدار را ×1 کن.","The local cycle is fixed: 2 minutes of day plus 2 minutes of night. Orbital speed is separate so the motion is visible. Set it to ×1 for a closer time ratio."],["لایه‌های دید","Visual Layers"],["ابرهای جوی","Clouds"],["هالهٔ جو","Atmosphere Glow"],["خطوط مدار","Orbit Lines"],["ستاره‌ها","Stars"],["تکامل قابل مشاهدهٔ حیات","Visible Life Evolution"],["آغاز","Start"],["خاموش","Off"],["زمین آغازین · بدون حیات","Early Earth · No Life"],["با آغاز آزمایش، نخستین موجودات ساده ظاهر می‌شوند و در گذر زمان به جانداران پیچیده‌تر می‌رسند. نشانه‌ها به‌صورت دیداری روی کره نمایش داده می‌شوند.","Start the experiment to see simple early organisms appear and gradually develop into more complex life. Markers are shown on the globe."],["مرحله:","Stage:"],["زمان تکامل:","Evolution Time:"],["سال مدل","model years"],["آغاز تکامل","Start Evolution"],["توقف تکامل","Pause Evolution"],["از ابتدا","Reset"],["سرعت تکامل","Evolution Speed"],["این یک مدل آموزشی ساده‌شده است؛ مراحل و زمان‌بندی برای نمایش سریع طراحی شده‌اند و تاریخ واقعی پیدایش حیات را بازسازی نمی‌کنند.","This is a simplified educational model. The stages and timing are designed for quick viewing and do not reconstruct the actual history of life."],["زیست‌کرهٔ میکروسکوپی","Microscopic Biosphere"],["شبیه‌سازی","Simulation"],["واحد جمعیت میکروبی مدل","modelled microbial population units"],["شاخص مناسب‌بودن محیط","Environmental Suitability Index"],["جمعیت تک‌سلولی، رشد و تغییراتش به‌صورت ریاضی مدل می‌شود. این موجودات داده‌ای داخل شبیه‌سازی‌اند و حیات واقعی تولید نمی‌شود.","The single-cell population and its changes are mathematical models. These are simulated data, not real organisms."],["مشخصات مرجع","Reference Specifications"],["شعاع سیاره","Planet Radius"],["جرم","Mass"],["گرانش سطح","Surface Gravity"],["دورهٔ مداری مرجع","Reference Orbital Period"],["مدل دیداری و آموزشی. هندسه، مقیاس فاصله‌ها و چرخهٔ زمان برای نمایش قابل‌فهم ساده‌سازی شده‌اند؛ شبیه‌ساز جایگزین مدل عددی کامل اقلیم یا اخترفیزیک نیست.","Educational visual model. Geometry, distances and time cycles are simplified for clarity; this is not a full numerical climate or astrophysics model."],["راهنما ؟","Help ?"],["پنل","Panel"],["متوجه شدم","Got it"],["این نسخه یک شبیه‌سازی تعاملی مستقل از سرور است. روی صفحه بکشید تا زاویهٔ دید تغییر کند؛ با چرخ ماوس یا ژست دو انگشتی، فاصلهٔ دوربین را تنظیم کنید.","This is an interactive simulation that does not require a server. Drag to change the view; use the mouse wheel or a two-finger gesture to adjust camera distance."],["هر چرخهٔ چرخش زمین ۴ دقیقه است: ۲ دقیقه روشنایی و ۲ دقیقه تاریکی؛ نور خورشید پیوسته روی کره حرکت می‌کند.","Each Earth rotation cycle lasts 4 minutes: 2 minutes of daylight and 2 minutes of darkness. Sunlight moves continuously across the globe."],["در نمای «منظومه»، خورشید و مدارهای سیاره‌ها با دوره‌های نسبی عطارد، زهره، زمین، مریخ، مشتری و زحل نمایش داده می‌شوند. اندازه‌ها و فاصله‌ها برای خوانایی بصری تغییر مقیاس دارند.","In Solar System view, the Sun and the orbits of Mercury, Venus, Earth, Mars, Jupiter and Saturn are shown with relative periods. Sizes and distances are scaled for visual clarity."],["سرعت مداری مستقل است؛ ×1 نسبت زمانی دقیق‌تری میان روز و سال دارد، و ×60 یا ×365 حرکت مدارها را سریع‌تر نشان می‌دهد.","Orbital speed is independent. ×1 gives a closer day/year time ratio; ×60 or ×365 makes orbital motion faster."],["اقلیم و جمعیت میکروبی مدل‌های آموزشی ساده‌شده‌اند، نه پیش‌بینی علمی معتبر یا موجودات واقعی.","Climate and microbial population are simplified educational models, not validated scientific forecasts or real organisms."],["هر خط تکاملی یک ژنوم دیجیتال دارد؛ جهش‌ها صفات را اندکی تغییر می‌دهند و انرژی، زیستگاه، رقابت و بقا بر فراوانی جمعیت اثر می‌گذارند.","Each lineage has a digital genome; mutations slightly change traits, while energy, habitat, competition and survival affect population size."],["برای دیدن فرم‌های تازه، تکامل را آغاز کن و نوار زمان را به مراحل درختان، آبزیان و خزندگان ببر. اندازه‌ها و فرم‌ها نمادین‌اند.","Start evolution and move the timeline to the tree, aquatic-life and reptile stages to see new forms. Sizes and shapes are illustrative."],["در صورت بازنشانی، وضعیت تکامل و فهرست گونه‌ها از نو آغاز می‌شود.","Resetting restarts the evolution state and species catalog."],["در حال تکامل","Evolving"],["مرحلهٔ نهایی","Final Stage"],["پایان مدل نمایشی","End of visual model"],["مولکول‌های خودتکثیرشونده","Self-replicating molecules"],["میکروب‌های تک‌سلولی","Single-celled microbes"],["فتوسنتز و جلبک‌ها","Photosynthesis and Algae"],["حیات چندسلولی","Multicellular Life"],["گیاهان و جانوران","Plants and Animals"],["زیست‌کرهٔ پیچیده","Complex Biosphere"],["هنوز هیچ جانداری نمایش داده نمی‌شود؛ تکامل را آغاز کن.","No organisms are shown yet. Start evolution."],["نخستین ساختارهای سادهٔ شیمیایی؛ نقاط ریز در محیط‌های آبی ظاهر می‌شوند.","Early simple chemical structures; tiny markers appear in aquatic environments."],["سلول‌های ساده گسترش می‌یابند و در اقیانوس‌ها لکه‌های میکروبی می‌سازند.","Simple cells spread and form microbial patches in the oceans."],["لایه‌های سبز و فیروزه‌ای در آب‌های کم‌عمق گسترش پیدا می‌کنند.","Green and turquoise layers spread through shallow waters."],["کلونی‌ها و جانداران دریایی پیچیده‌تر در نقاط مناسب زمین دیده می‌شوند.","Colonies and more complex marine life appear in suitable regions."],["پوشش سبز خشکی‌ها و نشانه‌های کوچک جانداران روی سطح ظاهر می‌شوند.","Green land cover and small signs of organisms appear on the surface."],["تنوع دیداری حیات به بیشترین سطح این مدل می‌رسد؛ این پایان مدل نمایشی است، نه پیش‌بینی علمی.","Visible diversity reaches the maximum in this model. This is the end of the visual model, not a scientific prediction."],["دقیقهٔ روز","minutes of daylight"],["شب","Night"],["مليون سال","million years"],["میلیون سال (مدل)","million years (model)"],["زمین","Earth"],["عطارد","Mercury"],["زهره","Venus"],["مریخ","Mars"],["مشتری","Jupiter"],["زحل","Saturn"],["آزمایشگاه ژنوم کامل","Full Genome Lab"],["ورود از فایل، شناسهٔ NCBI یا ENA","Import by file, NCBI accession or ENA"],["دریافت از NCBI / ENA","Fetch from NCBI / ENA"],["خواندن و اعتبارسنجی","Read and validate"],["تحلیل توالی واردشده","Analyze pasted sequence"],["نتیجهٔ بررسی ژنوم","Genome analysis results"],["طول کل توالی","Total sequence length"],["درصد GC","GC percentage"],["تعداد رکوردها / قطعات","Records / contigs"],["فراوانی آغازین نشانگر فرضی","Initial hypothetical marker frequency"],["اجرای سناریوی تکامل","Run evolution scenario"],["گزارش JSON","JSON report"],["بستن","Close"],["مدل تکامل جمعیت بر پایهٔ اندازهٔ ژنوم","Population evolution model based on genome length"],["گزارش مستند ژنوم","Genome Evidence Report"],["راهنمای کامل Planet","Complete Planet Guide"],["این راهنما برای بخش‌های اصلی برنامه است. بعضی داده‌ها و مدل‌های دیداری داخل دستگاه اجرا می‌شوند؛ دریافت ژنوم از پایگاه‌ها به اینترنت نیاز دارد.","This guide covers the main parts of the app. Some data and visual models run on-device; fetching genomes from databases requires internet access."],["۱. زمین و کنترل دوربین","1. Earth and camera controls"],["در نمای زمین، انگشت را روی کره بکش تا بچرخد. با ژست دو انگشتی یا چرخ ماوس فاصلهٔ دوربین را تغییر بده؛ دکمهٔ «بازنشانی زاویهٔ دید» نمای استاندارد را برمی‌گرداند.","In Earth view, drag the globe to rotate it. Use a two-finger gesture or mouse wheel to change camera distance; “Reset view” returns to the standard view."],["لایه‌های ابر، هالهٔ جو، مدارها و ستاره‌ها از پنل قابل روشن و خاموش کردن هستند.","Clouds, atmospheric glow, orbit lines and stars can be toggled in the panel."],["بافت باکیفیت زمین پس از بارگذاری، جزئیات خشکی‌ها، بیابان‌ها، جنگل‌ها و یخ‌های قطبی را واضح‌تر می‌کند. بارگذاری نقشهٔ برخط به اتصال اینترنت وابسته است؛ نسخهٔ اندروید بافت محلی هم دارد.","After loading, the higher-detail Earth texture makes land, deserts, forests and polar ice clearer. The web map needs an internet connection; the Android build also bundles a local texture."],["۲. منظومهٔ شمسی و زمان","2. Solar System and time"],["با «منظومه» به نمای خورشید و شش سیاره برو. برای زمین، چرخهٔ نمایش روز و شب چهار دقیقه است؛ لغزندهٔ سرعت، حرکت مداری را جداگانه تنظیم می‌کند. اندازه و فاصلهٔ سیارات برای دید بهتر مقیاس‌گذاری شده‌اند.","Choose “Solar System” to view the Sun and six planets. Earth’s display day/night cycle lasts four minutes; the speed slider controls orbital motion separately. Planet sizes and distances are scaled for visibility."],["۳. شبیه‌سازی محیط","3. Environment simulation"],["پنل محیطی شاخص‌های مدل مانند دما، فشار، ابر و ترکیب جو را نشان می‌دهد. این مقادیر خروجی یک مدل نمایشی‌اند، نه اندازه‌گیری زنده از زمین واقعی یا پیش‌بینی اقلیم اعتبارسنجی‌شده.","The environment panel shows model indicators such as temperature, pressure, clouds and atmospheric composition. These are model outputs, not live measurements of Earth or validated climate forecasts."],["۴. حیات دیجیتال و فهرست موجودات","4. Digital life and organism catalog"],["«آغاز تکامل» و نوار زمان، مراحل مدل‌شده را جلو می‌برند؛ از مکث برای توقف و از بازنشانی برای شروع اجرای تازه استفاده کن.","“Start evolution” and the timeline advance modeled stages; pause to stop and reset to begin a new run."],["«فهرست موجودات» وضعیت حضور یا انقراض در مدل، ژنوم دیجیتال، نسل، زیستگاه و جمعیت را نشان می‌دهد. «بررسی زیستگاه» اطلاعات افراد دیجیتال و رفتار مدل‌شده را باز می‌کند.","The organism catalog shows modeled presence or extinction, digital genome, generation, habitat and population. “Inspect habitat” opens details about digital individuals and their modeled behavior."],["«ساخت نمونهٔ آزمایشگاهی» یک نمونهٔ دستی می‌سازد و نباید با پیدایش طبیعی حیات اشتباه گرفته شود.","“Create lab specimen” creates a manual test specimen and should not be confused with natural abiogenesis."],["۵. آزمایشگاه ژنوم کامل","5. Full Genome Lab"],["از دکمهٔ «آزمایشگاه ژنوم کامل» می‌توانی شناسهٔ NCBI/ENA، فایل FASTA یا GenBank/GBFF، یا توالی را وارد کنی. برای مثال، شناسهٔ یک کروموزوم معمولاً با NC_ شروع می‌شود و شناسهٔ اسمبلی کامل می‌تواند با GCF_ یا GCA_ آغاز شود.","Use “Full Genome Lab” to enter an NCBI/ENA accession, a FASTA or GenBank/GBFF file, or a sequence. A chromosome accession often starts with NC_; a complete assembly accession may start with GCF_ or GCA_."],["این بخش طول توالی، درصد GC، رکوردها، N50، بازهای مبهم و ویژگی‌های ثبت‌شده در GenBank را گزارش می‌کند. سناریوی جمعیتی فعلی فقط یک نشانگر فرضی را مدل می‌کند؛ نتیجهٔ آن پیش‌بینی واقعی یک باکتری نیست.","This section reports sequence length, GC percentage, records, N50, ambiguous bases and features recorded in GenBank. The current population scenario models one hypothetical marker; it does not predict a real bacterium."],["۶. گزارش مستند ژنوم","6. Genome Evidence Report"],["در «گزارش مستند ژنوم» می‌توانی تمام بازهای ورودی را تحلیل کنی، شمارش k-merها و آمار توالی را ببینی و گزارش JSON، توالی FASTA و فهرست ویژگی‌ها را ذخیره کنی. برای استناد، رکورد منبع، روش تحلیل و هش SHA-256 را با فایل اصلی نگه دار.","In “Genome Evidence Report”, analyze all input bases, inspect k-mer counts and sequence statistics, and save JSON, full FASTA and a feature list. Keep the source record, analysis method and SHA-256 hash with the original file for reproducibility."],["محدودیت علمی مهم","Important scientific limitation"],["هنگام ساخت موجود دیداری از ژنوم مرجع، موتور حیات فعلی هنوز از پروکسی مصنوعی ۱۶۸ بازی استفاده می‌کند. این موجود شکل واقعی جاندار صاحب ژنوم را پیش‌بینی نمی‌کند. گزارش مستند، تحلیل کامل توالی است اما به‌تنهایی عملکرد ژن، متابولیسم یا فنوتیپ را اثبات نمی‌کند.","When creating a visual organism from a reference genome, the current life engine still uses a synthetic 168-base proxy. It does not predict the real shape of the source organism. The evidence report analyzes the complete sequence but does not by itself prove gene function, metabolism or phenotype."],["۷. دستیار و عیب‌یابی","7. Assistant and troubleshooting"],["دستیار Planet برای بررسی وضعیت، خطاهای ثبت‌شده و ارائهٔ پیشنهاد به کار می‌رود. پاسخ‌های آنلاین به تنظیم سرویس و اینترنت وابسته‌اند؛ پیشنهاد دستیار به معنی اصلاح خودکار و قطعی کد نیست.","The Planet assistant can inspect status, recorded errors and suggest improvements. Online responses depend on service setup and internet; suggestions do not mean the code is automatically and conclusively repaired."],["دربارهٔ برنامه و منابع","About the app and sources"],["PLANET یک شبیه‌ساز آموزشی مستقل برای کاوش سیاره، ژنوم و حیات دیجیتال است. همهٔ نتایج تکاملی و زیستی باید با توجه به محدودیت‌های مدل تفسیر شوند.","PLANET is an independent educational simulator for exploring a planet, genomes and digital life. Evolutionary and biological outputs must be interpreted within the model’s limitations."],["منبع بافت روز زمین: Solar System Scope؛ مجوز Creative Commons Attribution 4.0 (CC BY 4.0).","Earth day-map texture: Solar System Scope; the original 8K map is downscaled to 4K; CC BY 4.0 license."],["مشاهدهٔ بافت‌ها و مجوز","View textures and license"],["متن مجوز CC BY 4.0","CC BY 4.0 license text"],["نقشهٔ سطح زمین 4K","Earth surface map 4K"],["۱) دریافت از پایگاه‌های توالی","1) Retrieve from sequence databases"],["شناسهٔ توالی یا اسمبلی","Sequence or assembly accession"],["برای یک توالی NCBI از شناسه‌ای مانند NC_… یا CP… استفاده کن. برای اسمبلی کامل از GCF_… یا GCA_… استفاده کن. دریافت اسمبلی به اتصال اینترنت وابسته است.","For an NCBI sequence, use an accession such as NC_… or CP…. For a complete assembly, use GCF_… or GCA_…. Assembly downloads require internet."],["نمونه: E. coli K-12","Example: E. coli K-12"],["۲) وارد کردن فایل ژنوم","2) Import a genome file"],["فایل FASTA، GenBank یا آرشیو NCBI Datasets","FASTA, GenBank, or NCBI Datasets archive"],["فایل چندتوالی FASTA، GenBank متنی، فایل gzip و ZIP استاندارد اسمبلی پشتیبانی می‌شوند. در صورت خطای فایل‌گزین، نسخهٔ Android با انتخاب‌گر فایل سیستم ساخته شده است.","Multi-sequence FASTA, text GenBank, gzip, and standard NCBI assembly ZIP files are supported. If the file picker fails, use the Android build with the system file picker."],["۳) چسباندن توالی مستقیم","3) Paste a sequence directly"],["توالی DNA/RNA یا متن FASTA/GenBank","DNA/RNA sequence or FASTA/GenBank text"],["هنوز ژنومی وارد نشده است. یک شناسه، فایل یا توالی را انتخاب کن.","No genome has been imported yet. Choose an accession, file, or sequence."],["بازهای N","N bases"],["CDS در GenBank","CDS features in GenBank"],["۴) اتصال توالی واقعی به گونهٔ جانوری","4) Link the real sequence to a species"],["پس از واردکردن توالی، آن را به گونهٔ مناسب پیوند بده. توالی واقعی جدا از DNA مصنوعی کوتاهِ موتور تکامل نگهداری می‌شود تا دادهٔ علمی با مدل آموزشی اشتباه نشود.","After importing a sequence, link it to the appropriate species. The real sequence is kept separate from the evolution engine’s short synthetic DNA so scientific data are not confused with the educational model."],["گونه‌ای که این توالی به آن تعلق دارد","Species this sequence belongs to"],["ماهی گورخر — Danio rerio","Zebrafish — Danio rerio"],["قورباغهٔ پنجه‌دار — Xenopus tropicalis","Western clawed frog — Xenopus tropicalis"],["مگس سرکه — Drosophila melanogaster","Fruit fly — Drosophila melanogaster"],["موش خانگی — Mus musculus","House mouse — Mus musculus"],["مرغ — Gallus gallus","Chicken — Gallus gallus"],["سگ — Canis lupus familiaris","Dog — Canis lupus familiaris"],["گربه — Felis catus","Cat — Felis catus"],["اسب — Equus caballus","Horse — Equus caballus"],["فیل آفریقایی — Loxodonta africana","African elephant — Loxodonta africana"],["انسان — Homo sapiens","Human — Homo sapiens"],["ذخیره و پیوند توالی به گونه","Save and link sequence to species"],["بررسی پیوندهای ذخیره‌شده","Review saved links"],["ابتدا توالی را دریافت یا از فایل وارد کن.","Retrieve a sequence or import it from a file first."],["اندازهٔ مؤثر جمعیت (Ne)","Effective population size (Ne)"],["ضریب انتخاب برای نشانگر فرضی (s)","Selection coefficient for the hypothetical marker (s)"],["ساخت موجود دیجیتال از توالی واردشده","Create a digital organism from the imported sequence"],["قالب دیداری آزمایشی","Experimental visual template"],["میکروب / باکتری","Microbe / bacterium"],["آبزی / ماهی","Aquatic organism / fish"],["دوزیست","Amphibian"],["دایناسور گردن‌بلند (قالب فرضی)","Long-necked dinosaur (hypothetical template)"],["دایناسور دونده (قالب فرضی)","Running dinosaur (hypothetical template)"],["دایناسور زره‌پوش (قالب فرضی)","Armoured dinosaur (hypothetical template)"],["پستاندار","Mammal"],["پرنده","Bird"],["حشره","Insect"],["انسان‌مانند (قالب نمایشی)","Humanoid (display template)"],["ساخت مدل دیجیتال در زیست‌کره","Create a digital model in the biosphere"],["بعد از ورود ژنوم، سناریو را اجرا کن.","Import a genome, then run the scenario."],["۰ / ۹","0 / 9"],["۰٪","0%"],["آزمایشگاه ژنوم · قدرت خالق","Genome Lab · Creator Mode"],["ورود دستی DNA (فقط A/C/G/T؛ طول معتبر ژنوم)","Enter DNA manually (A/C/G/T only; valid genome length)"],["ساخت موجود از DNA","Create organism from DNA"],["ترکیب دو موجود از بایگانی","Combine two organisms from the archive"],["مدیریت بایگانی","Manage archive"],["اعلام انقراض موجود انتخاب‌شده","Declare selected organism extinct"],["ترکیب ژنوم، جهش و انقراض در این بخش تغییرات دیجیتال و آموزشی‌اند؛ DNA واقعی یک گونه را بازسازی نمی‌کنند.","Genome mixing, mutation, and extinction here are educational digital changes; they do not reconstruct a real species’ DNA."],["مدل سه‌بعدی در استودیوی نمایش مستقل","3D model in the separate viewing studio"],["این مدل در نمای جداگانه نمایش داده می‌شود؛ هندسه از صفات دیجیتال تولید شده و بازسازی تأییدشده از DNA خام نیست.","This model is shown separately. Its geometry is generated from digital traits and is not a validated reconstruction from raw DNA."],["موتور هوشمند آفلاین آماده است؛ تحلیل‌ها روی همین دستگاه انجام می‌شوند.","The offline engine is ready; analyses run on this device."],["بررسی سلامت برنامه","Check app health"],["پاک‌کردن حافظهٔ محلی","Clear local memory"],["گرفتن گزارش سلامت JSON","Export JSON health report"],["سلام! من دستیار تخصصی آفلاین PLANET هستم. بدون اینترنت می‌توانم خطاهای قابل‌مشاهده را بررسی کنم، دربارهٔ ژنوم و تکامل راهنمایی بدهم و پیشنهادهای قابل‌آزمایش ارائه کنم. داده‌ها برای پاسخ‌گویی به سرور ارسال نمی‌شوند.","Hello! I am PLANET’s offline specialist assistant. I can inspect visible errors, explain genomes and evolution, and offer testable suggestions without internet. Your data are not sent to a server."],["سؤالت را بنویس...","Type your question..."],["حالت پیش‌فرض کاملاً آفلاین است. موتور داخلی بدون اینترنت کار می‌کند و پیام‌ها را ارسال نمی‌کند.","The default mode is fully offline. The built-in engine works without internet and does not send messages."],["در حال تحلیل آفلاین…","Analysing offline…"],["تحلیل روی همین دستگاه انجام می‌شود؛ اتصال شبکه لازم نیست.","Analysis runs on this device; no network connection is required."],["تحلیل محلی انجام شد • بدون اینترنت","Local analysis complete • offline"],["خطا در موتور محلی","Local engine error"],["موتور آفلاین در دسترس نیست.","Offline engine is unavailable."],["موتور آفلاین بارگذاری نشده است. صفحه را تازه‌سازی کن و مطمئن شو فایل offline-ai.js در نسخهٔ نصب‌شده وجود دارد.","The offline engine did not load. Refresh the page and make sure offline-ai.js is included in the installed version."],["موتور آفلاین نتوانست این درخواست را پردازش کند.","The offline engine could not process this request."],["صفحه را تازه‌سازی کن؛ اگر ادامه داشت گزارش سلامت را بررسی کن.","Refresh the page; if the problem continues, check the health report."],["حافظهٔ گفت‌وگوی محلی پاک شد.","Local conversation memory cleared."],["ثبت خطای زمان اجرا:","Runtime error recorded:"],["خطای نامشخص","Unknown error"],["خطای ثبت‌شده را بررسی کن:","Inspect the recorded error:"],["در سوابق خطای محلیِ قابل دسترس، خطای ثبت‌شده‌ای دیده نشد؛ این به معنی بی‌خطا بودن کامل برنامه نیست.","No recorded errors were found in the available local log; this does not mean the app is entirely error-free."],["بخشی از رابط دستیار در DOM پیدا نشد.","Part of the assistant interface was not found in the DOM."],["صفحه را یک‌بار تازه‌سازی کن؛ اگر مشکل باقی ماند، فایل index.html و بارگذاری اسکریپت دستیار را بررسی کن.","Refresh the page once. If the issue remains, check index.html and assistant script loading."],["اسکریپت یا پنجرهٔ آزمایشگاه ژنوم پیدا نشد.","The genome lab script or panel was not found."],["ذخیره‌سازی محلی در دسترس نیست یا مرورگر آن را مسدود کرده است.","Local storage is unavailable or blocked by the browser."],["حالت خصوصی مرورگر و محدودیت فضای ذخیره‌سازی را بررسی کن؛ قابلیت‌های حافظهٔ محلی ممکن است محدود شوند.","Check private browsing mode and storage limits; local-memory features may be restricted."],["دستگاه آفلاین است؛ موتور تحلیل محلی همچنان باید کار کند.","The device is offline; the local analysis engine should still work."],["گزارش سلامت آفلاین PLANET v","PLANET offline health report v"],["امتیاز شاخص سلامت رابط:","Interface health score:"],["زمان:","Time:"],["شبکه:","Network:"],["آفلاین","Offline"],["متصل/گزارش‌شده","Online/reported"],["نامشخص","Unknown"],["یافته‌ها","یافته‌ها:"],["اقدامات پیشنهادی","اقدامات پیشنهادی:"],["دامنهٔ بررسی:","Inspection scope:"],["یافت شد","Found"],["یافت نشد","Not found"],["شناسه مرجع","Reference accession"],["شناسه ژنوم","Genome accession"],["پایگاه داده","Database"],["درصد جی سی","GC percentage"],["پیوستگی اسمبلی","Assembly contiguity"],["کدون","Codon"],["نوترکیبی","Recombination"],["انتخاب طبیعی","Natural selection"],["رانش ژنتیکی","Genetic drift"],["احتمال","Probability"],["شانس","Odds"],["پیش بینی","Prediction"],["گونه‌زایی","Speciation"],["موجود زنده","Living organism"],["روز شمار","Day counter"],["سال شمار","Year counter"],["گزارش سلامت","Health report"],["بررسی سلامت","Health check"],["سلامت برنامه","App health"],["پیشنهاد بهبود","Improvement suggestions"],["کار نمی‌کند","Does not work"],["لمس","Touch"],["کلیک","Click"],["باز نمی‌شود","Does not open"],["صفحه سفید","White screen"],["کرش","Crash"],["گرافیک","Graphics"],["یادت هست","Do you remember"],["گفت‌وگو","Conversation"],["پاک کن","Clear"],["اینترنت ندارم","I am offline"],["تحلیل تمام توالی ورودی، همراه با منشأ داده، اثرانگشت و محدودیت‌های علمی","Analyse the full input sequence, including provenance, fingerprint and scientific limitations"],["۱) منبع ژنوم","1) Genome source"],["می‌توانی یک فایل FASTA یا GenBank/GBFF کامل وارد کنی، توالی را بچسبانی، یا شناسهٔ NCBI/RefSeq را دریافت کنی. فایل GenBank/GBFF شامل annotation است؛ FASTA معمولاً فقط توالی را دارد.","Import a complete FASTA or GenBank/GBFF file, paste a sequence, or fetch an NCBI/RefSeq accession. GenBank/GBFF includes annotation; FASTA usually contains sequence only."],["شناسهٔ NCBI / RefSeq / Assembly","NCBI / RefSeq / Assembly accession"],["دریافت رکورد حاشیه‌نویسی‌شده","Fetch annotated record"],["استفاده از ژنوم فعلی Planet","Use the current Planet genome"],["فایل توالی یا آرشیو","Sequence file or archive"],["منبع/شناسه برای استناد (اختیاری)","Source/accession for citation (optional)"],["یا توالی / FASTA / متن GenBank را اینجا بچسبان","Or paste a sequence / FASTA / GenBank text here"],["تحلیل تمام توالی","Analyse full sequence"],["پاک کردن ورودی","Clear input"],["هنوز ژنومی تحلیل نشده است. Planet توالی را به ۱۶۸ باز تبدیل نمی‌کند؛ همهٔ رکوردهای واردشده بررسی می‌شوند یا در صورت ناسازگاری، تحلیل کامل رد می‌شود.","No genome has been analysed yet. Planet does not reduce the sequence to 168 bases; all imported records are analysed, or full analysis is rejected if incompatible."],["۲) نتیجهٔ قابل استناد","2) Reproducible results"],["ترکیب تمام توالی‌ها","Composition of all sequences"],["امضای کل ژنوم (k-mer)","Whole-genome signature (k-mer)"],["تعداد پنجره‌های هم‌پوشان ۲ و ۳ نوکلئوتیدی از تمام رکوردها محاسبه می‌شود؛ پنجره‌ای که باز مبهم دارد شمرده نمی‌شود. دو contig جدا به‌صورت مصنوعی به هم وصل نمی‌شوند.","Overlapping 2- and 3-nucleotide windows are counted across all records; ambiguous windows are excluded. Separate contigs are never artificially joined."],["Annotation دریافت‌شده از فایل","Annotation imported from file"],["دریافت گزارش کامل JSON","Download full JSON report"],["دریافت تمام توالی به FASTA","Download all sequences as FASTA"],["دریافت فهرست کامل ویژگی‌ها TSV","Download complete feature list as TSV"],["گزارش JSON همهٔ آمار، تمام ویژگی‌های استخراج‌شده از فایل حاشیه‌نویسی‌شده، شناسهٔ منبع، روش تحلیل و هش توالی را دربر می‌گیرد؛ خودِ توالی کامل به‌صورت فایل FASTA جداگانه قابل دریافت است.","The JSON report includes all statistics, features extracted from annotated files, source accession, analysis method and sequence hash. The complete sequence is available separately as FASTA."],["۳) معنی علمی نتیجه","3) Scientific interpretation"],["این نسخه تمام بازهای موجود در همهٔ رکوردهای ورودی را برای آمار پایه، GC، GC-skew، پنجره‌های GC و شمارش k-mer بررسی می‌کند. اگر فایل GenBank/GBFF باشد، ویژگی‌های ثبت‌شده مانند CDS، ژن، rRNA و tRNA هم از annotation همان فایل استخراج می‌شوند.","This version analyses every base in every input record for basic statistics, GC, GC-skew, GC windows and k-mer counts. For GenBank/GBFF, features such as CDS, genes, rRNA and tRNA are extracted from that file’s annotation."],["این گزارش به‌تنهایی عملکرد ژن، متابولیسم، شکل جانور، زنده‌مانی یا فنوتیپ را اثبات نمی‌کند. Annotation منبع نیز بدون اعتبارسنجی مستقل تأییدشده فرض نمی‌شود. در FASTA بدون annotation، برنامه ژن یا پروتئین را از خودش اختراع نمی‌کند.","This report alone does not prove gene function, metabolism, animal shape, viability or phenotype. Source annotation is not assumed validated without independent confirmation. For FASTA without annotation, the app does not invent genes or proteins."],["برای بازسازی متابولیسم میکروب باید annotation عملکردی و شبکهٔ واکنش‌های متابولیک/مدل ژنوم‌مقیاس به‌همراه شرایط محیطی به‌کار رود؛ برای جانوران و گیاهان مدل معتبر ژن‌به‌فنوتیپ عمومی و آماده‌ای وجود ندارد که از توالی به‌تنهایی شکل واقعی را تضمین کند.","Microbial metabolism reconstruction requires functional annotation, a metabolic reaction network or genome-scale model, and environmental conditions. No general ready-made gene-to-phenotype model can guarantee real animal or plant shape from sequence alone."],["منابع روش‌شناسی و استناد","Methodology and citation sources"],["پیش‌نمایش چرخان مدل سه‌بعدی","Rotating 3D model preview"],["انتخاب گونه","Select species"],["مولد سه‌بعدی موجودات · PLANET","PLANET · 3D Organism Generator"],["هندسهٔ سه‌بعدی در همین دستگاه و از پارامترهای فنوتیپی مدل ساخته می‌شود. برای چرخاندن، روی مدل بکش.","3D geometry is generated on this device from model phenotype parameters. Drag the model to rotate it."],["در حال یافتن گونه‌ها…","Finding species…"],["تولید / به‌روزرسانی","Generate / update"],["ابتدا یک گونه از بایگانی زیست‌کره انتخاب کن؛ اگر بایگانی خالی باشد، تکامل را آغاز کن یا از آزمایشگاه ژنوم مدل دیجیتال بساز.","Select a species from the biosphere archive first. If the archive is empty, start evolution or create a digital model in the genome lab."],["محدودیت علمی: این خروجی یک مدل دیداری رویه‌ای است، نه پیش‌بینی تأییدشدهٔ شکل بدن از توالی خام DNA. اگر ژنوم مرجع به پروکسی دیجیتال تبدیل شده باشد، آن پروکسی با ژنوم واقعی و فنوتیپ اندازه‌گیری‌شده یکسان نیست.","Scientific limitation: this is a procedural visual model, not a validated prediction of body shape from raw DNA. A digital proxy derived from a reference genome is not the real genome or a measured phenotype."],["ذخیره مدل سه‌بعدی (.glb)","Save 3D model (.glb)"],["تغییر زبان به فارسی","Switch language to Persian"],["Switch language to English","تغییر زبان به انگلیسی"],["PLANET — سیاست حریم خصوصی / Privacy Policy","PLANET — Privacy Policy"],["NC_000913.3 یا GCF_000005845.2","NC_000913.3 or GCF_000005845.2"],["این نسخهٔ WebView فشرده‌سازی","This WebView version does not support compression"],["را پشتیبانی نمی‌کند؛ فایل متنیِ از حالت فشرده خارج‌شده را وارد کن.","; import the decompressed text file."],["داخل ZIP فایل FASTA ژنوم پیدا نشد. فایل genomic.fna یا FASTA را جداگانه انتخاب کن.","No genome FASTA file was found inside the ZIP. Select genomic.fna or FASTA separately."],["ساختار ZIP قابل‌خواندن نیست.","The ZIP structure cannot be read."],["روش فشرده‌سازی ZIP پشتیبانی نمی‌شود.","This ZIP compression method is not supported."],["هیچ توالی قابل‌خواندنی پیدا نشد.","No readable sequence was found."],["هیچ توالی‌ای پیدا نشد. قالب FASTA یا GenBank را بررسی کن.","No sequence was found. Check the FASTA or GenBank format."],["نماد نامعتبر در توالی پیدا شد؛ فقط حروف استاندارد IUPAC ژنوم پذیرفته می‌شوند.","Invalid symbols were found; only standard genomic IUPAC characters are accepted."],["توالی خالی است.","The sequence is empty."],["مرورگر IndexedDB را پشتیبانی نمی‌کند.","This browser does not support IndexedDB."],["بازکردن پایگاه محلی ناموفق بود.","Could not open the local database."],["در حال ذخیرهٔ توالی در حافظهٔ محلی…","Saving sequence to local storage…"],["ذخیرهٔ توالی انجام نشد.","Could not save the sequence."],["ذخیره لغو شد.","Save cancelled."],["پیوند ذخیره شد:","Link saved:"],["باز ·","Open ·"],["ذخیره انجام نشد:","Save failed:"],["هنوز توالی واقعی به گونه‌ای پیوند داده نشده است.","No real sequence has been linked to a species yet."],["ناموجود در FASTA","Not present in FASTA"],["شناسه/نام:","Accession/name:"],["· نوع:","· Type:"],["· منبع:","· Source:"],["· تاریخ ورود:","· Import date:"],["ژنوم آماده است. پارامترها را انتخاب کن و سناریوی آماری را اجرا کن.","Genome is ready. Select parameters and run the statistical scenario."],["ژنوم با موفقیت خوانده و بررسی اولیه شد.","Genome was read and passed initial checks."],["ورودی کاربر","User input"],["پاسخ FASTA معتبر برنگرداند.","did not return valid FASTA."],["رکوردی پیدا نشد.","No record was found."],["قالب شناسه نامعتبر است.","The accession format is invalid."],["در حال دریافت توالی از پایگاه عمومی؛ برای اسمبلی کامل ممکن است دریافت چند دقیقه طول بکشد…","Fetching sequence from a public database; a complete assembly may take several minutes…"],["دریافت اسمبلی کامل ناموفق بود. خطای NCBI:","Complete assembly retrieval failed. NCBI error:"],["؛ خطای ENA:","; ENA error:"],[". راه جایگزین: فایل genomic.fna یا ZIP اصلی اسمبلی را وارد کن.",". Alternative: import genomic.fna or the original assembly ZIP."],["رکورد GenBank بدون بخش ORIGIN پیدا شد: ممکن است فایل کامل نباشد.","GenBank record has no ORIGIN section; the file may be incomplete."],["توالی ORIGIN خالی است:","The ORIGIN sequence is empty:"],["نماد غیرنوکلئوتیدی دارد؛ تحلیل ناقص انجام نشد.","Non-nucleotide symbols were found; partial analysis was not performed."],["فایل GenBank خوانده نشد؛ فایل GB/GBFF کامل یا FASTA وارد کن.","Could not read the GenBank file; import a complete GB/GBFF or FASTA file."],["نماد غیرنوکلئوتیدی دارد؛ توالی پروتئینی یا فایل خراب است و پذیرفته نشد.","Non-nucleotide symbols found; protein sequences or corrupt files are not accepted."],["هیچ توالی نوکلئوتیدی پیدا نشد. FASTA، GenBank یا توالی A/C/G/T معتبر وارد کن.","No nucleotide sequence was found. Import valid FASTA, GenBank, or an A/C/G/T sequence."],["تحلیل تمام بازها: رکورد","Full-base analysis: record"],["، جایگاه",", position"],["شمارش تمام پنجره‌های k-mer: رکورد","All k-mer windows counted: record"],["نشانی سرویس معتبر نیست.","The service URL is invalid."],["برای امنیت، سرویس باید HTTPS باشد.","For security, the service must use HTTPS."],["تنظیمات روی همین دستگاه ذخیره شد.","Settings saved on this device."],["ذخیره‌سازی مرورگر در دسترس نیست.","Browser storage is unavailable."],["هنوز تصویری تولید نشده است.","No image has been generated yet."],["اطلاعات ژنوم این جاندار در دسترس نیست.","Genome information for this organism is unavailable."],["تصویر به‌صورت محلی از ژنوم دیجیتال و محیط ساخته شد؛ بدون اینترنت، سرویس بیرونی یا تصویر آماده. این مولد هندسی است، نه مدل انتشار تصویرِ آموزش‌دیده.","The image was generated locally from digital genome and environment data, without internet, an external service or a pre-made image. This is a geometric generator, not a trained image-diffusion model."],["در حال تولید…","Generating…"],["پاسخ سرویس تصویر نداشت.","The service response contained no image."],["تولید شد. این یک پیشنهاد بصری بر پایهٔ صفات دیجیتال و محیط است، نه پیش‌بینی زیستی اعتبارسنجی‌شده.","Generated. This is a visual suggestion based on digital traits and environment, not a validated biological prediction."],["درخواست بیش از حد طول کشید.","The request timed out."],["سرویس آنلاین در دسترس نبود (","The online service was unavailable ("],["). تصویر محلی ساخته شد.","). A local image was generated."],["این تصویر مولد رویه‌ای است، نه خروجی مدل انتشار آموزش‌دیده.","This is a procedurally generated image, not output from a trained diffusion model."],["✨ تولید تصویر هوش مصنوعی","✨ Generate AI image"],["◈ ساخت مدل ۳بعدی","◈ Create 3D model"],["ساخت و خروجی مدل سه‌بعدی موجود زنده","Create and export a 3D organism model"],["مولد هندسه سه‌بعدی موجودات","3D organism geometry generator"],["بستن ×","Close ×"],["بخش «زبان»","Language section"],["ورود از فایل، شناسهٔ NCBI یا ENA؛ مناسب ژنوم باکتری‌ها، پلاسمیدها و توالی‌های چندقطعه‌ای.","Import a file, NCBI or ENA accession; supports bacterial genomes, plasmids and multi-contig sequences."],["محدودیت علمی: بررسی حرف‌ها، طول و GC به‌تنهایی کامل‌بودن اسمبلی، هویت گونه یا عملکرد ژن‌ها را اثبات نمی‌کند. ژنوم واقعی در این بخش تحلیل می‌شود؛ برای پرهیز از ادعای نادرست، صفات و رفتار باکتری از روی توالی به‌طور کامل پیش‌بینی نمی‌شوند. مدل تکامل زیر یک مدل آماریِ آموزشی است.","Scientific limitation: character, length and GC checks alone do not prove assembly completeness, species identity or gene function. This section analyses the real genome; bacterial traits and behaviour are not fully predicted from sequence. The evolution model below is educational and statistical."],["تعداد نسل‌ها","Number of generations"],["نرخ جهش فرضی به‌ازای هر جایگاه/نسل","Hypothetical mutation rate per site/generation"],["فراوانی آغازین نشانگر (۰ تا ۱)","Initial marker frequency (0 to 1)"],["برنامه ژنوم واقعی را مستقیماً به شکل بدن تبدیل نمی‌کند. یک پروکسی مصنوعی ۱۶۸ بازی برای شبیه‌سازی می‌سازد؛ فرم زیر فقط قالب دیداری آزمایشی است و پیش‌بینی علمی فنوتیپ نیست.","The app does not directly convert a real genome into body shape. It creates a synthetic 168-base proxy for simulation; the form below is only an experimental visual template, not a scientific phenotype prediction."],["گیاه","Plant"],["۰ میلیون سال","0 million years"],["Planet 0.1 · مدل دیداری و آموزشی. هندسه، مقیاس فاصله‌ها و چرخهٔ زمان برای نمایش قابل‌فهم ساده‌سازی شده‌اند؛ شبیه‌ساز جایگزین مدل عددی کامل اقلیم یا اخترفیزیک نیست.","Planet 0.1 · Educational visual model. Geometry, distances and time cycles are simplified for clarity; this is not a full numerical climate or astrophysics model."],["فهرست موجودات ایجادشده · منقرض‌شده:","Generated organism catalog · extinct:"],["ترکیب ژنوم و ساخت نسل تازه","Combine genomes and create a new generation"],["◈ ساخت مدل سه‌بعدی این موجود","◈ Create a 3D model of this organism"],["مدل سه‌بعدی را در نمای مستقل بررسی کن؛ روی کرهٔ زمین نمایش داده نمی‌شود.","Inspect the 3D model in a separate view; it is not displayed on the Earth globe."],["بازگشت به فهرست گونه‌ها","Return to species catalog"],["منبع بافت روز زمین: Solar System Scope؛ نقشهٔ اصلی 8K به بافت 4K کوچک‌سازی شده است؛ مجوز CC BY 4.0.","Earth day-map source: Solar System Scope; the original 8K map is downscaled to 4K; CC BY 4.0 license."],["Planet | گزارش مستند ژنوم","Planet | Genome Evidence Report"],["NCBI GenBank — ساختار Feature Table و qualifierها","NCBI GenBank — Feature Table and qualifiers"],["NCBI Entrez Programming Utilities — دریافت رکوردها","NCBI Entrez Programming Utilities — record retrieval"],["KBase — بازسازی مدل‌های متابولیک از annotation عملکردی","KBase — metabolic model reconstruction from functional annotation"],["eggNOG-mapper — روش annotation بر پایهٔ orthology","eggNOG-mapper — orthology-based annotation method"],["Planet Genome Evidence · روش تحلیل: همهٔ رکوردها و تمام بازهای فایل ورودی؛ بدون کوتاه‌سازی به ژنوم مصنوعی. برای نتایج متابولیک/فنوتیپی، مدل‌های اختصاصی و اعتبارسنجی جداگانه لازم‌اند.","Planet Genome Evidence · Analysis method: all records and all bases in the input file, without reducing to a synthetic genome. Metabolic/phenotypic results require dedicated models and separate validation."],["چه اطلاعاتی استفاده می‌شود؟","What information is used?"],["انتخاب زبان فارسی یا انگلیسی ممکن است فقط در حافظهٔ محلی برنامه/مرورگر ذخیره شود تا در اجرای بعدی حفظ بماند.","Your Persian/English language choice may be stored locally by the app/browser for the next launch."],["اشتراک‌گذاری، نگهداری و حذف","Sharing, retention and deletion"],["کودکان و حریم خصوصی","Children and privacy"],["تماس دربارهٔ حریم خصوصی","Privacy contact"],["آخرین به‌روزرسانی: ۱۷ اکتبر ۲۰۲۶","Last updated: October 17, 2026"],["سیاست حریم خصوصی PLANET","PLANET Privacy Policy"],["یک نشانه از از دست‌رفتن زمینهٔ WebGL در صفحه پیدا شد.","A possible WebGL context-loss indicator was found on the page."],["وضعیت اتصال شبکه برای موتور محلی اهمیتی ندارد؛ این گزارش به سرور ارسال نمی‌شود.","Network status does not affect the local engine; this report is not sent to a server."],["محدودیت: موتور محلی فقط DOM، خطاهای ثبت‌شده و چند نشانهٔ قابل مشاهده را بررسی می‌کند؛ به پشتهٔ کامل خطای سیستم‌عامل یا تمام متغیرهای درونی شبیه‌سازی دسترسی ندارد.","Limitation: the local engine checks only the DOM, recorded errors and a few visible signals; it cannot access the full operating-system error stack or all internal simulation variables."],["مورد از گزارش‌های در دسترس.","items from available reports."],["بررسی کن بلوک gp-genome-lab-script و gpGenomeOverlay در نسخهٔ منتشرشده حاضر باشند.","Check that gp-genome-lab-script and gpGenomeOverlay exist in the published build."],["در حال حاضر عنصری از نوع canvas دیده نمی‌شود؛ شاید نمای گرافیکی هنوز ساخته نشده یا در این صفحه وجود ندارد.","No canvas element is currently visible; the graphics view may not have been created yet or may not exist on this page."],["برای بررسی کامل‌تر، عملیات مشکل‌دار را دوباره اجرا کن و زمان، دکمهٔ فشرده‌شده و متن خطای دقیق را نگه دار.","For a fuller diagnosis, repeat the failing operation and record the time, button pressed and exact error text."],["اولویت خیلی بالا — خطاهای ثبت‌شده را بر اساس زمان و محل وقوع گروه‌بندی کن؛ ابتدا خطاهای تکرارشونده را رفع و پس از هر تغییر آزمون بازگشتی اجرا کن.","Very high priority — group recorded errors by time and location; fix recurring errors first and run regression tests after each change."],["اولویت بالا — ذخیره‌سازی را با مدیریت خطای quota و پیام روشن برای کاربر ایمن کن؛ برای تصمیم‌های علمی مهم فقط به حافظهٔ محلی متکی نباش.","High priority — handle storage quota errors safely and show clear messages; do not rely only on local storage for important scientific decisions."],["اولویت بالا — برای ورود ژنوم، اعتبارسنجی فایل و توالی را جدا از تحلیل زیستی نگه دار؛ فرمت، طول، نویز و رکوردهای ناشناخته را پیش از اجرای مدل گزارش کن.","High priority — separate file/sequence validation from biological analysis; report format, length, ambiguity and unknown records before running the model."],["اولویت بالا — خروجی‌های تکاملی را با seed تصادفی قابل ثبت، چند اجرای تکراری، بازهٔ عدم‌قطعیت و تعریف روشن فرضیات ارائه کن.","High priority — report evolution outputs with reproducible random seeds, repeated runs, uncertainty intervals and explicit assumptions."],["اولویت متوسط — هر هشدار را به سه بخش «مشاهدهٔ واقعی»، «تفسیر محتمل» و «آزمایش تأییدی» تقسیم کن تا احتمال با واقعیت اشتباه نشود.","Medium priority — separate warnings into observed fact, possible interpretation and confirming test so hypotheses are not mistaken for facts."],["اولویت متوسط — برای هر تغییر مهم، آزمون خودکار کوتاه بنویس: ورودی معتبر، فایل خراب، ژنوم خالی، قطع اینترنت، ذخیره‌سازی مسدود و صفحه با حافظهٔ محدود.","Medium priority — add short automated tests for valid input, corrupt files, empty genomes, offline mode, blocked storage and low-memory pages."],["اولویت متوسط — در صفحهٔ حریم خصوصی، روشن کن که گفتگو و گزارش‌های محلی ذخیره می‌شوند یا نه؛ امکان پاک‌کردن تاریخچه را همیشه نگه دار.","Medium priority — clarify whether local conversations and reports are stored; always provide a way to clear history."],["تغییر زبان به انگلیسی","Switch language to English"],["PLANET — سیاست حریم خصوصی","PLANET — Privacy Policy"],["بازگشت به PLANET","Return to PLANET"],["ذخیره در حافظهٔ محلی مرورگر انجام می‌شود و به فضای کافی نیاز دارد؛ برای جلوگیری از هنگ‌کردن گوشی، این مرحله توالی‌های بزرگ‌تر از ۱۰۰ مگابایت را نمی‌پذیرد. برای اسمبلی‌های چندگیگابایتی، توالی ژن/کروموزوم مشخص یا فایل کوچک‌تر را وارد کن. این پیوند به‌تنهایی اثر فنوتیپی ژن یا آلل را اثبات نمی‌کند.","Data are saved in browser local storage and require sufficient space. To prevent the phone from freezing, this step rejects sequences larger than 100 MB. For multi-gigabyte assemblies, import a specific gene/chromosome sequence or a smaller file. This link alone does not prove a gene or allele’s phenotypic effect."],["طول ژنوم واردشده در محاسبهٔ فشار جهش استفاده می‌شود. فراوانی یک نشانگر فرضی با انتخاب طبیعی و رانش ژنتیکی مدل می‌شود؛ این خروجی، بازسازی دقیق تکامل آن باکتری نیست.","Imported genome length is used to calculate mutation pressure. The frequency of a hypothetical marker is modelled using natural selection and genetic drift; this is not an exact reconstruction of that bacterium’s evolution."],["این موتور تخصصی مبتنی بر قواعد داخلی است، نه مدل زبانی بزرگ. پاسخ‌های احتمالاتی فقط با فرضیات و داده‌های مشخص معتبرند.","This specialist engine uses internal rules, not a large language model. Probabilistic answers are valid only with explicit assumptions and data."],["حریم خصوصی","Privacy"],["✦ دستیار هوشمند","✦ AI Assistant"],["✦ دستیار هوشمند PLANET","✦ PLANET AI Assistant"],["تنظیمات","Settings"],["ارسال","Send"],["یافته‌ها:\n","Findings:\n"],["اقدامات پیشنهادی:\n","Recommended actions:\n"],["پیشنهادهای بهبود آفلاین PLANET\n\n","PLANET offline improvement suggestions\n\n"],["تحلیل خطای آفلاین PLANET\n\n","PLANET offline error analysis\n\n"],["سلام! من موتور هوشمند آفلاین PLANET هستم؛ بدون اینترنت هم کار می‌کنم و پیام تو را به سرور نمی‌فرستم.\n\n","Hello! I am PLANET’s offline intelligence engine. I work without internet and do not send your message to a server.\n\n"],["Planet Genome — آزمایشگاه ژنوم، شبیه‌سازی حیات و تکامل موجودات بر پایه داده‌های ژنتیکی و محیطی","Planet Genome — Genome lab, life simulation and organism evolution based on genetic and environmental data"],["نمودار تغییر فراوانی نشانگر در نسل‌ها","Marker frequency across generations"],["متن/FASTA","Text/FASTA"],["ابتدا ژنوم واقعی را وارد کن.","Import a real genome first."],["این توالی از سقف ۱۰۰ مگابایت این مرحله بزرگ‌تر است. برای جلوگیری از بسته‌شدن برنامه، یک ژن/کروموزوم مشخص یا فایل کوچک‌تر وارد کن.","This sequence exceeds this step’s 100 MB limit. To prevent the app from closing, import a specific gene/chromosome or a smaller file."],["رکورد. توالی واقعی در IndexedDB نگهداری می‌شود؛ ژنوتیپ کوتاه شبیه‌سازی عمداً تغییر نکرده است.","record. The real sequence is stored in IndexedDB; the simulation’s short genotype was intentionally not changed."],[". فضای خالی مرورگر را بررسی کن و دوباره تلاش کن.",". Check available browser storage and try again."],["پیوندهای ذخیره‌شده:\n","Saved links:\n"],["; ذخیره","; saved"],["\nاین اطلاعات در همین دستگاه است.","\nThis information stays on this device."],["\nقالب:","\nFormat:"],["\nمنبع:","\nSource:"],["\nتاریخ ورود:","\nImport date:"],["\nبازهای مبهم IUPAC:","\nAmbiguous IUPAC bases:"],["\nتوجه: تحلیل اولیهٔ ساختار و حروف است، نه اثبات کامل‌بودن ژنوم.","\nNote: this is an initial structural and character check, not proof of genome completeness."],["باز در","bases in"],["رکورد.","record."],["سرویس NCBI Datasets پاسخ HTTP","NCBI Datasets returned HTTP"],["NCBI EFetch مستقیم","Direct NCBI EFetch"],["NCBI EFetch پس از جست‌وجو","NCBI EFetch after search"],["دریافت از NCBI برای شناسهٔ","NCBI retrieval for accession"],["ناموفق بود. جزئیات:","failed. Details:"],["سرویس ENA پاسخ HTTP","ENA returned HTTP"],["پاسخ ENA به شکل FASTA نیست.","The ENA response is not in FASTA format."],["یک accession معتبر وارد کن؛ مثلاً NC_000913.3 یا GCF_000005845.2.","Enter a valid accession, e.g. NC_000913.3 or GCF_000005845.2."],["انرژی و سوخت‌وساز","Energy and metabolism"],["حس‌کردن محیط","Environmental sensing"],["پوشش و حفاظت","Cover and protection"],["تحمل دما","Temperature tolerance"],["سیاره تازه شکل گرفته است. مدل هنوز موجود زنده‌ای را نمایش نمی‌دهد؛ منشأ دقیق حیات واقعی همچنان یک پرسش علمی باز است.","The planet has just formed. The model does not yet display living organisms; the exact origin of real life remains an open scientific question."],["آب مایع، منابع انرژی و شیمی کربن‌محور می‌توانند زمینه‌ساز حیات باشند؛ مسیر دقیق پیدایش اولین سامانهٔ زنده معلوم نیست.","Liquid water, energy sources and carbon chemistry may enable life; the exact path to the first living system remains unknown."],["شواهد شناخته‌شدهٔ حیات باستانی به میکروب‌های ساده اشاره دارند. نمونه‌های این مرحله دیجیتال‌اند و بازسازی ژنتیکی یک فسیل واقعی نیستند.","Known evidence of ancient life points to simple microbes. Specimens at this stage are digital, not genetic reconstructions of real fossils."],["برخی خط‌های حیات مدل‌شده انرژی نور را به کار می‌گیرند. زمان‌بندی آغاز فتوسنتز اولیه عدم قطعیت قابل‌توجهی دارد.","Some modelled lineages use light energy. The timing of early photosynthesis remains highly uncertain."],["قارچ‌ها و چرخهٔ تجزیه","Fungi and decomposition cycle"],["فرم‌های قارچ‌مانند برای نمایش چرخهٔ مواد و تجزیه ظاهر می‌شوند. زیست‌شناسی و رده‌بندی قارچ‌ها در این مدل به‌طور کامل شبیه‌سازی نمی‌شود.","Fungus-like forms illustrate nutrient cycling and decomposition. Fungal biology and taxonomy are not fully simulated in this model."],["با تغییر صفات ژنومیِ مدل، فرم‌های گیاهی بلندتر و شبیه درخت روی خشکی نمایش داده می‌شوند. این گذار برای آموزش ساده‌سازی شده است.","As model genomic traits change, taller tree-like plant forms appear on land. This transition is simplified for education."],["فرم‌های خشکی‌زیِ کشیده‌تر با دُم نمادین نمایش داده می‌شوند. زمان‌بندی تقریبی است و هدف، نمایش تنوع فرم بدن است.","Elongated land-dwelling forms with illustrative tails appear. Timing is approximate and intended to show body-form diversity."],["در خط زمانی ساده‌شده، تبارهای دایناسور غیرپرنده از زیست‌کرهٔ فعال حذف می‌شوند؛ پرندگان در علم امروز از تبار دایناسورها به‌شمار می‌روند، اما مدل حاضر آن‌ها را جداگانه بازسازی نمی‌کند.","In this simplified timeline, non-avian dinosaur lineages are removed from the active biosphere. Modern science classifies birds as dinosaurs, but this model does not reconstruct them separately."],["در چند میلیون سال پایانیِ خط زمانی، فرم‌های دوپای انسان‌مانند فقط به‌عنوان نمایش دیداری ظاهر می‌شوند. این یک گونهٔ واقعی، پیش‌بینی ژنتیکی یا بازسازی دقیق تاریخ انسان نیست.","In the final few million years of the timeline, humanoid biped forms appear only as visuals. This is not a real species, genetic prediction or accurate reconstruction of human history."],["به انتهای بازهٔ ۴٫۵۴ میلیاردسالهٔ مدل رسیده‌ای. این بازه، تاریخ زمین را ساده می‌کند و همهٔ رویدادهای واقعی را بازسازی نمی‌کند.","You have reached the end of the model’s 4.54-billion-year interval. It simplifies Earth’s history and does not reconstruct every real event."],["رنگ چشم","Eye colour"],["ژن کلاسیک Drosophila؛ اثر به آلل و زمینهٔ ژنتیکی وابسته است.","Classic Drosophila gene; effects depend on allele and genetic background."],["جرم عضلانی نسبی","Relative muscle mass"],["نقش زیستی شناخته‌شده؛ اندازه‌گیری و زمینهٔ ژنتیکی لازم است.","Known biological role; measurement and genetic context are required."],["ارتباط ژن-رنگ شناخته‌شده؛ آلل و زمینهٔ نژادی مهم است.","Known gene–colour association; allele and breed background matter."],["ارتباط ژن-صفت شناخته‌شده؛ به آلل نیاز است","Known gene–trait association; allele data are required"],["/100 (ابتدایی و مبتنی بر قواعد؛ نه آزمون جامع نرم‌افزار)\n","/100 (preliminary and rule-based; not a comprehensive software test)\n"],["اسکریپت در صفحه؛","Script on page;"],["بوم canvas؛ رابط دستیار","Canvas; assistant interface"],["؛ آزمایشگاه ژنوم","; genome lab"],["\n\nاین پیشنهادها از روی قواعد عمومیِ ایمنی و معماری تولید شده‌اند؛ برای اعلام اینکه یک مورد واقعاً ایراد برنامه است، باید شواهد قابل مشاهده یا آزمون بازتولیدپذیر داشته باشیم.","\n\nThese suggestions are based on general safety and architecture rules; visible evidence or a reproducible test is needed to confirm an actual bug."],["درصد gc","GC percentage"],["ترکیب باز","Base composition"],["درصد بازها","Base percentages"],["تحلیل GC به‌صورت آفلاین\n\n","Offline GC analysis\n\n"],["درصد GC از رابطهٔ 100 × (تعداد G + تعداد C) / تعداد بازهای معتبر محاسبه می‌شود. باید مشخص شود N و حروف مبهم از مخرج حذف می‌شوند یا جداگانه گزارش می‌شوند؛ بهتر است هر دو تعداد معتبر و تعداد مبهم نمایش داده شوند.\n","GC percentage is calculated as 100 × (G count + C count) / valid-base count. N and ambiguous characters should be excluded from the denominator or reported separately; ideally both valid and ambiguous counts are shown.\n"],["ان ۵۰","N50"],["ان50","N50"],["تفسیر N50\n\nN50 طولی است که وقتی قطعات اسمبلی از بلند به کوتاه مرتب شوند، جمع طول قطعاتی که به آن طول یا بلندترند دست‌کم به ۵۰٪ طول کل اسمبلی برسد. N50 بزرگ‌تر گاهی نشانهٔ پیوستگی بیشتر است، اما صحت توالی یا کامل بودن زیستی را به‌تنهایی نشان نمی‌دهد.","N50 interpretation\n\nN50 is the length at which contigs, sorted longest to shortest, cumulatively cover at least 50% of the assembly. A larger N50 can indicate greater contiguity, but does not alone establish sequence accuracy or biological completeness."],["کدکننده","Coding"],["ژن کدکننده","Coding gene"],["ترجمه ژن","Gene translation"],["تحلیل CDS و کدون‌ها\n\nبرای ترجمهٔ قابل اتکا باید جدول کد ژنتیکی مناسب، قاب خوانش، جهت رشته، کدون آغاز/پایان و استثناهای annotation مشخص باشند. حدس CDS صرفاً با جست‌وجوی ATG تا کدون پایان ممکن است ژن‌های واقعی را از دست بدهد یا ORFهای تصادفی گزارش کند؛ در گزارش، CDS پیش‌بینی‌شده را از CDS ثبت‌شده در GenBank جدا نگه دار.","CDS and codon analysis\n\nReliable translation requires the correct genetic code, reading frame, strand direction, start/stop codons and annotation exceptions. Guessing CDS by searching from ATG to a stop codon can miss real genes or report random ORFs; keep predicted CDS separate from GenBank-annotated CDS."],["راهنمای مدل جهش و انتخاب\n\nجهش، نوترکیبی، انتخاب و رانش ژنتیکی سازوکارهای متفاوت‌اند و باید پارامترهای جدا داشته باشند. هر نتیجه به اندازهٔ جمعیت، نرخ جهش، وراثت‌پذیری، فشار انتخابی و تعداد تکرار وابسته است. یک اجرای تصادفی شاهد کافی نیست؛ اجراها را با seedهای ثبت‌شده تکرار و میانگین و دامنهٔ نتایج را گزارش کن.","Mutation and selection model guide\n\nMutation, recombination, selection and genetic drift are distinct mechanisms and need separate parameters. Results depend on population size, mutation rate, heritability, selection pressure and replication count. One random run is insufficient; repeat runs with recorded seeds and report the mean and range."],["راهنمای ژنوم آفلاین\n\nموتور محلی می‌تواند منطق ورود فایل، اعتبارسنجی حروف، آمار توالی و تفسیر مفاهیم را توضیح دهد. برای تحلیل دقیق یک ژنوم مشخص، فایل یا توالی باید در همین دستگاه در دسترس باشد.\n\n","Offline genome guide\n\nThe local engine can explain file import, character validation, sequence statistics and concepts. To analyse a specific genome accurately, the file or sequence must be available on this device.\n\n"],["FASTA: توالی خام و سربرگ رکورد.","FASTA: raw sequence and record header."],["GenBank: توالی به‌همراه annotation در صورت وجود.","GenBank: sequence with annotation when available."],["دادهٔ مبهم (N و IUPAC) باید جدا گزارش شود، نه اینکه خودکار به A/C/G/T تبدیل شود.","Ambiguous bases (N and IUPAC codes) should be reported separately, not automatically converted to A/C/G/T."],["آمار توالی با اثبات عملکرد ژن یا بازسازی کامل زیست‌شیمی یکسان نیست.","Sequence statistics are not proof of gene function or a complete biochemical reconstruction."],["دربارهٔ احتمال و پیش‌بینی\n\nبرای ارائهٔ یک احتمال عددی معتبر، باید رویداد، بازهٔ زمانی، پارامترهای مدل و دادهٔ کالیبراسیون معلوم باشند. بدون این موارد عدد دقیق قابل دفاع نیست.\n\n","Probability and prediction\n\nA defensible numerical probability requires a defined event, time horizon, model parameters and calibration data. Without these, a precise number is not justified.\n\n"],["تعریف کن چه رویدادی شمرده می‌شود (مثلاً انقراض در ۱۰۰ نسل).","Define the event being counted (for example, extinction within 100 generations)."],["شرایط اولیه و پارامترهای هر اجرا را ثبت کن.","Record initial conditions and parameters for each run."],["اجرای تصادفی را بارها با seedهای مختلف تکرار کن.","Repeat stochastic runs with different seeds."],["احتمال تجربی را برابر تعداد اجراهای رخداد / کل اجراها گزارش کن و فاصلهٔ عدم‌قطعیت را نیز بیاور.","Report empirical probability as event runs divided by total runs, with an uncertainty interval."],["این عدد فقط تحت فرضیات مدل معتبر است و لزوماً احتمال وقوع در طبیعت نیست.","This value is valid only under model assumptions and is not necessarily the probability in nature."],["راهنمای علمی شبیه‌سازی تکامل\n\nدر PLANET باید ویژگی‌های مدل‌شده را از زیست‌شناسی واقعی جدا کنیم. برای تکامل دیجیتال، وراثت، تغییر ژنتیکی، تنوع صفات، موفقیت متفاوت در بقا/تولیدمثل و محدودیت محیط باید تعریف و قابل ردیابی باشند.\n\n","Scientific guide to evolution simulation\n\nPLANET must distinguish modelled traits from real biology. Digital evolution should define and track inheritance, genetic change, trait variation, differential survival/reproduction and environmental constraints.\n\n"],["تغییرات جمعیت و صفات را در طول نسل ثبت کن.","Record population and trait changes across generations."],["چند تکرار با seed ثابت و متغیر مقایسه کن.","Compare repeated runs with fixed and varied seeds."],["انقراض را طبق تعریف کمی مشخص ثبت کن.","Record extinction using a clear quantitative definition."],["نتایج را آموزشی/مدلی برچسب بزن؛ آن‌ها اثبات پیدایش حیات یا پیش‌بینی قطعی تکامل طبیعی نیستند.","Label results as educational/model outputs; they do not prove abiogenesis or predict natural evolution with certainty."],["دربارهٔ هوش و موجودات دیجیتال\n\nیک عامل دیجیتال می‌تواند حسگرهای ساده، حافظه، سیاست انتخاب عمل و یادگیری از پاداش داشته باشد. این رفتار به‌خودی‌خود نشان‌دهندهٔ آگاهی یا تجربهٔ ذهنی نیست.\n\nبرای ارزیابی بهتر، تعریف قابل سنجش انتخاب کن: عملکرد در وظیفهٔ تازه، تعمیم به محیط جدید، پایداری تصمیم، هزینهٔ منابع و توان سازگاری. امتیاز داخلی مدل را با «هوش واقعی» یا آگاهی برابر ندان.","Digital intelligence and organisms\n\nA digital agent can have simple sensors, memory, an action-selection policy and reward-based learning. This behaviour alone does not demonstrate consciousness or subjective experience.\n\nFor evaluation, choose measurable criteria: performance on new tasks, generalisation, decision stability, resource cost and adaptability. Do not equate an internal model score with real intelligence or consciousness."],["راهنمای مدل سیاره‌ای\n\nبرای ارزیابی شبیه‌سازی سیاره، مشخص کن کدام بخش فیزیکی است و کدام بخش دیداری/آموزشی. مقیاس زمانی شتاب‌داده‌شده، داده‌های تقریبی و نمای بصری را با زمان واقعی یا محاسبهٔ نجومی دقیق یکی ندان.\n\n","Planetary model guide\n\nIdentify which parts of a planetary simulation are physical and which are visual/educational. Do not equate accelerated time, approximate data or visuals with real time or precise astronomical calculations.\n\n"],["واحدها را صریح نگه دار: ثانیهٔ شبیه‌سازی، روز، سال و زمان نجومی.","Label units clearly: simulation seconds, days, years and astronomical time."],["در برابر تغییر timestep آزمون پایداری انجام بده.","Test stability under timestep changes."],["در گزارش ارسالی خطای ثبت‌شده‌ای موجود نیست. این به‌تنهایی ثابت نمی‌کند برنامه سالم است؛ ممکن است رخداد پیش از ثبت گزارش یا داخل WebView/سیستم رخ داده باشد.","No recorded error is present in the submitted report. This alone does not prove the app is healthy; an event may have occurred before logging or inside WebView/the system."],["برای عیب‌یابی دقیق‌تر، مرحلهٔ بازتولید، دکمهٔ فشرده‌شده، متن دقیق خطا و اینکه مشکل بعد از تازه‌سازی باقی می‌ماند یا نه را ثبت کن.","For precise troubleshooting, record reproduction steps, the button pressed, the exact error, and whether it remains after refresh."],["برای رابط: شناسهٔ عنصر را در DOM بررسی کن، listener دوباره ثبت نشود، رویداد pointer/click دوبار اجرا نشود و لایه‌بندی z-index/position با transform والدها تداخل نداشته باشد.","UI: inspect the element ID in the DOM, prevent duplicate listeners and pointer/click events, and check z-index/position against transformed ancestors."],["برای عملکرد: تعداد موجودات/ذرات، حافظهٔ مدل و تعداد فراخوانی‌های هر فریم را اندازه بگیر؛ ابتدا با تعداد کمتر، دستگاه سرد/گرم و چند اجرای تکراری مقایسه کن.","Performance: measure organism/particle counts, model memory and calls per frame; compare smaller counts, cold/warm devices and repeated runs."],["پیام خالی است. دربارهٔ خطای برنامه، شبیه‌سازی سیاره، احتمالات تکامل یا آزمایشگاه ژنوم سؤال کن.","The message is empty. Ask about an app error, planet simulation, evolution probabilities or the genome lab."],["نوبت اخیر قابل ذخیره است. این حافظه در localStorage مرورگر/برنامه نگهداری می‌شود و برای این موتور به سرور ارسال نمی‌شود.\nبرای پاک‌کردن آن، از تنظیمات دستیار گزینهٔ پاک‌سازی حافظه را به کار ببر.","The latest turn can be saved. This memory stays in browser/app localStorage and is not sent to a server by this engine.\nTo clear it, use the assistant settings’ clear-memory option."],["من در حالت کاملاً آفلاین، بر پایهٔ دانش و قواعد تخصصی داخلی پاسخ می‌دهم. برای جلوگیری از حدس نادرست، پرسش‌های خیلی کلی را به موضوع مشخص‌تری محدود می‌کنم.\n\n","I answer fully offline using internal specialist knowledge and rules. To avoid guessing, I narrow very broad questions to a more specific topic.\n\n"],["می‌توانم در این حوزه‌ها کمک کنم:\n","I can help with these topics:\n"],["تشخیص خطاهای ثبت‌شده و بررسی سلامت اجزای رابط","Diagnosing recorded errors and checking interface health"],["تحلیل مفاهیم ژنوم، GC، N50، CDS و دریافت accession","Explaining genomes, GC, N50, CDS and accession retrieval"],["تکامل دیجیتال، جهش، انتخاب طبیعی، انقراض و عدم‌قطعیت","Digital evolution, mutation, natural selection, extinction and uncertainty"],["پیشنهادهای فنی و علمی با روش آزمون","Technical and scientific suggestions with test methods"],["\n\nاگر خطایی داری، بگو دقیقاً چه کاری انجام دادی و چه چیزی دیدی.","\n\nIf you have an error, describe exactly what you did and what happened."],["با تغییر شیمی محیط، انتخاب طبیعی به سود و زیان راهبردهای سوخت‌وسازی متفاوت عمل می‌کند. این یک تقریب مدل است.","As environmental chemistry changes, natural selection favours or disfavors different metabolic strategies. This is a model approximation."],["زیست‌شناسی پیچیده در تاریخ واقعی به فرایندهای متعددی از جمله همزیستی وابسته بود؛ مدل فقط بخشی از این فشارها را تقریب می‌زند.","Complex biology in real history depended on many processes, including symbiosis; this model approximates only some of those pressures."],["جانداران چندسلولی در محیط‌های دریایی دیجیتال پدیدار می‌شوند؛ شکل‌های دیداری نمادین‌اند و فسیل دقیق گونه‌ای نیستند.","Multicellular organisms appear in digital marine environments; the visuals are illustrative, not exact species fossils."],["گیاهان سادهٔ خشکی در این مرحلهٔ آموزشی ظاهر می‌شوند؛ این نمایش یک بازسازی دقیق از گونه‌های واقعی نیست.","Simple land plants appear in this educational stage; this is not an exact reconstruction of real species."],["در محیط آبی، فرم‌های کشیده‌تر و شناگر نمادین می‌شوند؛ مدل ژنوم واقعی ماهی‌ها را بازسازی نمی‌کند.","In aquatic environments, elongated swimming forms appear as illustrations; the model does not reconstruct real fish genomes."],["عصر دایناسورها","Age of Dinosaurs"],["در این بازهٔ آموزشی، چند تبار دیجیتال دایناسور با فرم‌های گیاه‌خوار گردن‌بلند، دوندهٔ گوشت‌خوار و زره‌پوش ظاهر می‌شوند. زمان‌ها تقریبی‌اند و این موجودات بازسازی ژنوم گونه‌های فسیلی واقعی نیستند.","In this educational interval, digital dinosaur lineages appear as long-necked herbivores, running carnivores and armoured forms. Dates are approximate; these are not genome reconstructions of real fossil species."],["پس از انقراض کرتاسه–پالئوژن","After the Cretaceous–Paleogene extinction"],["اندازهٔ دیداری جانداران با صفات ژنومی، رشد و مرحلهٔ زمانی مدل تغییر می‌کند؛ این به معنای پیش‌بینی تکامل واقعی نیست.","Organism appearance and size vary with genomic traits, growth and model time; this does not predict real evolution."],["فرم‌های انسان‌مانند نمادین","Illustrative humanoid forms"],["جست‌وجوی غذا","Forage"],["کاوش محیط","Explore environment"],["استراحت و ترمیم","Rest and recover"],["دوری از خطر","Avoid danger"],["تولیدمثل","Reproduce"],["همکاری با هم‌نوع","Cooperate with peers"],["دایناسور گردن‌بلند گیاه‌خوار","Long-necked herbivorous dinosaur"],["دایناسور دوندهٔ گوشت‌خوار","Running carnivorous dinosaur"],["دایناسور زره‌پوش","Armoured dinosaur"],["رنگ‌دانه‌سازی و رشد سلول‌های رنگدانه‌ای","Pigment production and pigment-cell growth"],["الگوی رنگ و تعداد سلول‌های رنگدانه‌ای","Colour pattern and pigment-cell count"],["نقش زیستی شناخته‌شده؛ اثر آلل باید با دادهٔ گونه بررسی شود","Known biological role; allele effects require species-specific data"],["پاسخ به هورمون تیروئید در دگردیسی","Thyroid hormone response during metamorphosis"],["زمان و مرحلهٔ دگردیسی","Timing and stage of metamorphosis"],["نقش ژنی شناخته‌شده؛ پیش‌بینی آلل‌محور نیازمند اعتبارسنجی اختصاصی Xenopus است","Known gene role; allele-based prediction requires Xenopus-specific validation"],["ساخت ملانین","Melanin production"],["میزان/الگوی رنگدانه","Pigment amount/pattern"],["نقش زیستی شناخته‌شده؛ فنوتیپ از حضور ژن به‌تنهایی استنتاج نمی‌شود","Known biological role; phenotype cannot be inferred from gene presence alone"],["انتقال رنگدانهٔ چشم","Eye pigment transport"],["رنگدانهٔ بدن","Body pigment"],["شدت رنگ بدن","Body colour intensity"],["رشد بال","Wing growth"],["شکل/اندازهٔ بال","Wing shape/size"],["اثر جهش‌های خاص شناخته‌شده؛ از توالی کلی به‌تنهایی پیش‌بینی نمی‌شود","Effects of specific mutations are known; the overall sequence alone cannot predict them"],["ساخت رنگدانه و رنگ پوشش","Pigment production and coat colour"],["رنگ و توزیع رنگدانه","Pigment colour and distribution"],["ارتباط ژنی شناخته‌شده؛ تعیین رنگ به آلل‌ها و چندژنی‌بودن وابسته است","Known genetic association; colour depends on alleles and polygenic effects"],["تنظیم رشد عضله","Muscle growth regulation"],["نقش زیستی شناخته‌شده؛ اندازه‌گیری و زمینهٔ ژنتیکی لازم است","Known biological role; measurement and genetic context are required"],["رنگدانهٔ پر","Feather pigment"],["الگوی رنگ پر","Feather colour pattern"],["رنگدانهٔ پر/پوست","Feather/skin pigment"],["نقش زیستی شناخته‌شده؛ ژنوتیپ واقعی باید تحلیل شود","Known biological role; the actual genotype must be analysed"],["طول مو","Hair length"],["طول پوشش مو","Hair-coat length"],["واریانت‌های مشخص در چند نژاد با موی بلند مرتبط‌اند؛ این برنامه هنوز واریانت را صداگذاری نمی‌کند","Specific variants are associated with long hair in some breeds; this app does not call variants yet"],["رنگ پوشش","Coat colour"],["رنگ و الگوی پوشش","Coat colour and pattern"],["چندژنی؛ یک ژن به‌تنهایی برای پیش‌بینی کافی نیست","Polygenic; one gene alone is insufficient for prediction"],["تنظیم عضله","Muscle regulation"],["شاخص‌های تودهٔ عضلانی","Muscle-mass indicators"],["اثر وابسته به واریانت و نژاد؛ بدون فراخوانی واریانت قابل پیش‌بینی نیست","Effects depend on variant and breed; prediction requires variant calling"],["واریانت‌های مشخص با موی بلند مرتبط‌اند؛ آلل باید مستقیماً بررسی شود","Specific variants are associated with long hair; the allele must be checked directly"],["رنگدانهٔ پوست و مو","Skin and hair pigment"],["چندژنی و وابسته به آلل","Polygenic and allele-dependent"],["رنگ پایهٔ پوشش","Base coat colour"],["واریانت‌های مشخص اثر شناخته‌شده دارند؛ ترکیب آلل‌ها مهم است","Specific variants have known effects; allele combinations matter"],["تنظیم رشد عضله و عملکرد","Muscle growth and performance regulation"],["شاخص‌های عضلانی/عملکردی","Muscle/performance indicators"],["برخی واریانت‌ها با تیپ عملکرد مرتبط‌اند؛ این به‌تنهایی پیش‌بینی قطعی نیست","Some variants are associated with performance type; this is not a definitive prediction"],["چندژنی/وابسته به جنس","Polygenic/sex-dependent"],["رشد عاج","Tusk growth"],["وجود و اندازهٔ عاج","Tusk presence and size"],["ویژگی پیچیده و وابسته به جنس/جمعیت؛ این مدل ادعای یک ژن تعیین‌کننده نمی‌کند","A complex sex- and population-dependent trait; this model does not claim a single determining gene"],["ساخت بتاگلوبین هموگلوبین","Haemoglobin beta-globin production"],["نوع هموگلوبین و شاخص‌های گلبول قرمز","Haemoglobin type and red blood cell indicators"],["فعالیت لاکتاز/تحمل لاکتوز","Lactase activity/lactose tolerance"],["تنظیم بیان وابسته به تبار و واریانت؛ حضور ژن LCT به‌تنهایی کافی نیست","Expression regulation depends on ancestry and variants; LCT presence alone is insufficient"],["میزان/نوع ملانین","Melanin amount/type"],["صفت چندژنی؛ پیش‌بینی دقیق نیازمند مدل واریانت‌محور است","Polygenic trait; accurate prediction requires a variant-based model"],["راهنمای شناسه و پایگاه ژنومی در حالت آفلاین\n\n","Offline genome accession and database guide\n\n"],["• شناسهٔ accession به‌تنهایی توالی کامل را در دستگاه ایجاد نمی‌کند؛ برای واکشی از NCBI/ENA معمولاً اینترنت لازم است.\n","• An accession alone does not create the full sequence on the device; fetching from NCBI/ENA usually requires internet.\n"],["• اگر توالی یا فایل همان شناسه قبلاً روی دستگاه ذخیره نشده باشد، موتور آفلاین باید صادقانه بگوید داده در دسترس نیست، نه اینکه ژنوم را حدس بزند.\n","• If the sequence or file for an accession is not already stored locally, the offline engine should say it is unavailable rather than guess the genome.\n"],["• برای استفاده بدون اینترنت، فایل FASTA یا GenBank را از قبل وارد کن. نام accession، منبع، نسخهٔ رکورد و تاریخ دریافت را نگه دار.\n","• For offline use, import the FASTA or GenBank file in advance. Keep the accession, source, record version and retrieval date.\n"],["• پس از ورود، طول توالی، نویسه‌های مجاز، تعداد رکوردها و در صورت وجود annotation را بررسی کن.\n\n","• After import, check sequence length, valid characters, record count and any available annotation.\n\n"],["محدودیت علمی: آمار پایه‌ای توالی به‌تنهایی عملکرد ژن، فنوتیپ یا رفتار جاندار را ثابت نمی‌کند.","Scientific limitation: basic sequence statistics alone do not establish gene function, phenotype or organism behaviour."],["نسبت GC به‌تنهایی برای تعیین گونه یا پیش‌بینی کارکرد زیستی کافی نیست. برای مقایسه، از توالی‌های هم‌نوع، نسخهٔ مشخص و روش یکسان استفاده کن.","GC ratio alone is not enough to identify a species or predict biological function. Compare sequences of the same type and version using the same method."],["یک آزمایش کنترل با خاموش‌کردن انتخاب یا جهش اجرا کن.","Run a control experiment with selection or mutation disabled."],["برای مدارها و چرخش، پارامترها و منبع داده را ثبت کن.","Record parameters and data sources for orbits and rotation."],["حدود دقت و فرضیات هر مدل را کنار نتایج نشان بده.","Show each model’s accuracy limits and assumptions alongside its results."],["اقدام: ابتدا اولین خطای زمانی را بررسی کن؛ خطاهای بعدی ممکن است پیامد همان خطای اول باشند. یک تغییر انجام بده، دوباره همان مرحله را اجرا کن و نتیجه را مقایسه کن.","Action: inspect the earliest error first; later errors may be consequences. Make one change, repeat the same step and compare results."],["نمای سه‌بعدی منظومه سیاره‌ای","3D planetary system view"],["نمایش پنل","Show panel"],["سرعت تکامل حیات","Life evolution speed"],["توالی DNA را وارد کن...","Enter a DNA sequence..."],["والد اول","Parent 1"],["والد دوم","Parent 2"],["انتخاب موجود برای انقراض","Select organism for extinction"],["مدل سه‌بعدی مستقل موجود","Independent 3D organism model"],["دستیار هوشمند PLANET","PLANET AI Assistant"],["پیام به دستیار","Message the assistant"],["مثلاً NC_000913.3 یا URL مقاله/رکورد","For example, NC_000913.3 or a paper/record URL"],["حافظهٔ محلی در دسترس نیست.","Local memory is unavailable."],["خطا در موتور محلی: حافظهٔ محلی در دسترس نیست.","Local engine error: local memory is unavailable."],["ژن کلاسیک Drosophila؛ اثر به آلل و زمینهٔ ژنتیکی وابسته است","Classic Drosophila gene; effects depend on allele and genetic background."],["ارتباط ژن-رنگ شناخته‌شده؛ آلل و زمینهٔ نژادی مهم است","Known gene–colour association; allele and breed background matter."],["واریانت‌های مشخص مستندند؛ تفسیر نیازمند ژنوتیپ و زمینهٔ بالینی است","Specific variants are documented; interpretation requires genotype and clinical context."],["LCT و نواحی تنظیمی","LCT and regulatory regions"],["پایداری بیان لاکتاز در بزرگسالی","Persistence of lactase expression in adulthood"],["MC1R و ژن‌های دیگر","MC1R and other genes"],["رنگدانه‌سازی","Pigment production"],["ماهی استخوانی (مدل آموزشی)","Bony fish (educational model)"],["مرجع ژنومی ماهی گورخر؛ نمایندهٔ آموزشی ماهیان استخوانی، نه نیای مستقیم همهٔ ماهی‌ها.","Zebrafish genome reference; an educational representative of bony fish, not the direct ancestor of all fish."],["دوزیست (مدل آموزشی)","Amphibian (educational model)"],["مرجع ژنومی قورباغهٔ پنجه‌دار غربی؛ زمان پیدایش تبار دوزیستان بسیار قدیمی‌تر و تقریبی است.","Western clawed frog genome reference; amphibian lineage dates are much older and approximate."],["حشره (مگس سرکه)","Insect (fruit fly)"],["ژنوم مرجع مگس سرکه؛ نمایندهٔ حشرات امروزی است.","Fruit fly genome reference; a representative of modern insects."],["پستاندار (مدل آموزشی)","Mammal (educational model)"],["مرجع ژنومی موش خانگی؛ نمایندهٔ پستانداران امروزی، نه ژنوم نیای مشترک پستانداران.","House mouse genome reference; a representative of modern mammals, not the genome of the common mammalian ancestor."],["پرنده (مرغ خانگی)","Bird (domestic chicken)"],["مرجع ژنومی مرغ؛ پرندگان از نظر تکاملی دایناسورهای زنده‌اند.","Chicken genome reference; evolutionarily, birds are living dinosaurs."],["سگ اهلی","Domestic dog"],["ژنوم مرجع سگ؛ تاریخ اهلی‌سازی و ریشهٔ جمعیت‌های سگ پیچیده و محل پژوهش است.","Dog genome reference; domestication history and dog population origins are complex and still studied."],["گربهٔ اهلی","Domestic cat"],["ژنوم مرجع گربهٔ اهلی.","Domestic cat genome reference."],["اسب اهلی","Domestic horse"],["ژنوم مرجع اسب؛ تاریخ اهلی‌سازی در این خط زمانی نمایش ساده‌شده دارد.","Horse genome reference; domestication history is simplified in this timeline."],["فیل آفریقایی","African elephant"],["ژنوم مرجع فیل آفریقایی؛ زمان ورود به خط زمانی تقریبی است.","African elephant genome reference; its timeline placement is approximate."],["انسان خردمند (Homo sapiens)","Modern human (Homo sapiens)"],["ژنوم مرجع انسان؛ پیدایش گونهٔ ما حدود ۳۰۰ هزار سال پیش برآورد می‌شود.","Human genome reference; our species is estimated to have emerged around 300,000 years ago."],["مدل ژنتیکی داخلی کوتاه و آموزشی است؛ توالی مرجع کامل با این DNA مصنوعی جایگزین نشده و فنوتیپ از توالی مرجع استنتاج نمی‌شود.","The internal genetic model is short and educational; this synthetic DNA does not replace a complete reference sequence, and phenotype is not inferred from the reference sequence."],["میلیارد سال پس از شکل‌گیری زمین","billion years after Earth formed"],["میلیون سال پس از شکل‌گیری زمین","million years after Earth formed"],["٪ · حفاظت:","% · Protection:"],["· پروکسی ۱۶۸ بازی؛ اطمینان فنوتیپی بسیار کم","· 168-base proxy; very low phenotype confidence"],["جاندارِ رویه‌ای بر پایهٔ DNA","DNA-driven procedural organism"],["هنوز موجودی پدید نیامده است. تکامل را شروع کن و زمان زمین‌شناختی را به بازهٔ پیدایش حیات برسان، یا یک نمونهٔ تصادفیِ آزمایشگاهی بساز.","No organism has appeared yet. Start evolution and move geological time to the origin-of-life interval, or create a random lab specimen."],["اقیانوس","Ocean"],["ژنوم مرجع واقعی:","Actual reference genome:"],["ژنوم مرجع پیوند داده شده؛ ژنوتیپ شبیه‌سازی از آن ساخته نشده است.","The reference genome is linked; the simulation genotype was not generated from it."],["رکورد NCBI","NCBI record"],["پیوندهای ژن و صفتِ مستند:","Documented gene–trait links:"],["نقش ژن‌ها بر پایهٔ دانش زیستی است؛ تا وقتی واریانت‌ها اعتبارسنجی نشوند، فنوتیپ از DNA پیش‌بینی نمی‌شود.","Gene roles are based on biological knowledge; phenotype cannot be predicted from DNA until variants are validated."],["توالی مرجع واقعیِ واردشده:","Imported real reference sequence:"],["توالی در همین دستگاه ذخیره شده؛ فنوتیپ از آن استنتاج نشده است.","The sequence is stored on this device; phenotype has not been inferred from it."],["بررسی زیستگاه","Inspect habitat"],["صفحه را تازه‌سازی کن، تب‌های سنگین دیگر را ببند و در صورت تکرار، حافظهٔ دستگاه و خطاهای گرافیکی را بررسی کن.","Refresh the page, close other heavy tabs, and if it repeats, check device memory and graphics errors."],["دریافت ژنوم","Fetch genome"],["چقدر احتمال","How likely"],["پیش‌بینی","Prediction"],["گونه زایی","Speciation"],["انقراض","Extinction"],["یادگیری","Learning"],["موجودات","Organisms"],["خورشید","Sun"],["در گزارش محلی","In the local report"],["رخداد خطا وجود دارد:","An error event exists:"],["خطای ثبت‌شده","Recorded error"],["— فایل","— file"],["باز نمیشود","Does not open"],["ناپدید","Disappears"],["می پرد","Jumps"],["تشخیص سلامت","Health diagnostics"],["پیشنهاد بده","Make a suggestion"],["چه چیزی را بهتر","What should be improved"],["چطور بهتر","How to improve"],["بهبود برنامه","Improve the app"],["پیشنهادات","Suggestions"],["بررسی سلامت رابط و خطاهای ثبت‌شده","Check interface health and recorded errors"],["راهنمای ژنوم، FASTA/GenBank و محدودیت‌های accession آفلاین","Genome, FASTA/GenBank and offline accession guidance"],["تحلیل علمی تکامل، جهش و احتمال‌ها","Scientific guidance on evolution, mutation and probability"],["پیشنهادهای قابل‌آزمایش برای بهبود برنامه","Testable suggestions for improving the app"],["\n\nمن یک موتور تخصصی مبتنی بر قواعد و دانش داخلی هستم، نه مدل زبانی بزرگ؛ برای پرسش‌های ناشناخته ممکن است پاسخ محدود باشد.","\n\nI am a specialist engine based on internal rules and knowledge, not a large language model; answers to unfamiliar questions may be limited."],["سرور هنوز Secret کلید OpenAI را تنظیم نکرده است.","The server has not configured the OpenAI API key secret."],["تعداد درخواست‌ها زیاد است؛ یک دقیقه دیگر دوباره امتحان کن.","Too many requests; try again in one minute."],["درخواست بیش از اندازه بزرگ است.","The request is too large."],["درخواست JSON معتبر نیست.","The JSON request is invalid."],["پیام خالی است.","The message is empty."],["ارتباط با سرویس هوش مصنوعی برقرار نشد. اینترنت و تنظیمات سرور را بررسی کن.","Could not connect to the AI service. Check your internet connection and server settings."],["محدودیت درخواست سرویس هوش مصنوعی؛ بعداً دوباره امتحان کن.","AI service rate limit reached; try again later."],["سرویس OpenAI درخواست را نپذیرفت. کلید، دسترسی مدل و اعتبار حساب سرور را بررسی کن.","The OpenAI service rejected the request. Check the API key, model access and server account credits."],["پاسخ متنی از مدل دریافت نشد.","No text response was received from the model."],["پاسخی دریافت نشد؛ لطفاً دوباره تلاش کن.","No response was received; please try again."],["سناریوی محیطی برای آزمایش فرضیه‌ها","Environmental scenario for testing hypotheses"],["دهانه‌های گرمابی اقیانوسی","Ocean hydrothermal vents"],["حوضچه‌های آتشفشانی/آب شیرین","Volcanic / freshwater ponds"],["حوضچه‌های کم‌عمق و چرخهٔ تر/خشک","Shallow pools with wet–dry cycles"],["سناریوی ترکیبی با عدم‌قطعیت","Mixed scenario with uncertainty"],["چند محیط ممکن را بررسی می‌کند؛ محل دقیق پیدایش حیات معلوم نیست. این پارامترها سناریوهای آزمایشی‌اند، نه بازسازی قطعی زمین باستان.","This explores several possible environments; the exact location where life originated is unknown. These are experimental scenarios, not a definitive reconstruction of ancient Earth."],["سناریوهای علمی برای مقایسه:","Scientific scenarios for comparison:"],["شیمی پیش‌زیستی و زمین آغازین","Prebiotic Chemistry and Early Earth"],["آزمایشگاه سناریوهای کیهان","Cosmology Scenario Lab"],["مدل‌های مه‌بانگ، تورم، جهان جهشی و چرخه‌ای را در یک صفحهٔ جداگانه مقایسه کن؛ منحنی‌ها شماتیک‌اند و اثبات تجربی نیستند.","Compare Big Bang, inflation, bouncing-universe and cyclic models on a separate page; the curves are schematic, not experimental proof."],["باز کردن آزمایشگاه کیهان‌شناسی ↗","Open Cosmology Lab ↗"],["آزمایشگاه کیهان‌شناسی","Cosmology Lab"]];const enFrom=pairs.slice().sort((a,b)=>b[0].length-a[0].length);const faFrom=pairs.slice().sort((a,b)=>b[1].length-a[1].length);function transform(value,to){let out=String(value==null?'':value);const list=to==='en'?enFrom:faFrom;const isWord=c=>!!c&&(/[A-Za-z0-9_]/.test(c)||(c.codePointAt(0)>=0x600&&c.codePointAt(0)<=0x6ff));for(const p of list){const from=to==='en'?p[0]:p[1],dest=to==='en'?p[1]:p[0];if(!from)continue;let start=0,at;while((at=out.indexOf(from,start))!==-1){const before=at?out[at-1]:'';const after=out[at+from.length]||'';if((!isWord(from[0])||!isWord(before))&&(!isWord(from[from.length-1])||!isWord(after))){out=out.slice(0,at)+dest+out.slice(at+from.length);start=at+dest.length;}else start=at+from.length;}}if(to==='en')out=out.replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c));return out;}function translateTree(node,lang){if(!node)return;const doc=root.document;const walker=doc.createTreeWalker(node,root.NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){if(n.parentElement&&!n.parentElement.closest('#languageToggle,#planetLanguageToggle,input,textarea,select,script,style,code,pre,.lang-fa,.lang-en,[data-no-translate],.planet-ai-msg.user')){const v=transform(n.nodeValue,lang);if(v!==n.nodeValue)n.nodeValue=v;}}const attrs=['aria-label','title','placeholder','alt','value'];const selector='[aria-label],[title],[placeholder],[alt],button[value],input[type="button"][value],input[type="submit"][value]';if(node.querySelectorAll){const els=[];if(node.nodeType===1&&node.matches(selector))els.push(node);node.querySelectorAll(selector).forEach(el=>els.push(el));els.forEach(el=>attrs.forEach(a=>{if((a==='value')&&!(el.matches('button[value],input[type="button"][value],input[type="submit"][value]')))return;const v=el.getAttribute(a);if(v){const t=transform(v,lang);if(t!==v)el.setAttribute(a,t);}}));}}function initStandalone(){const doc=root.document;let b=doc.getElementById('planetLanguageToggle');if(!b){b=doc.createElement('button');b.id='planetLanguageToggle';(doc.querySelector('.head')||doc.querySelector('main')||doc.body).prepend(b);}let lang='fa';try{lang=root.localStorage.getItem('planet-language')==='en'?'en':'fa';}catch(e){}function apply(next){lang=next==='en'?'en':'fa';doc.documentElement.lang=lang;doc.documentElement.dir=lang==='fa'?'rtl':'ltr';b.textContent=lang==='fa'?'EN':'FA';b.setAttribute('aria-label',lang==='fa'?'Switch language to English':'تغییر زبان به فارسی');doc.title=transform(doc.title,lang);translateTree(doc.body,lang);doc.querySelectorAll('[data-planet-lang-fa]').forEach(e=>e.hidden=lang==='en');doc.querySelectorAll('[data-planet-lang-en]').forEach(e=>e.hidden=lang==='fa');try{root.localStorage.setItem('planet-language',lang);}catch(e){}}b.addEventListener('click',()=>apply(lang==='fa'?'en':'fa'));root.addEventListener('storage',e=>{if(e.key==='planet-language'&&e.newValue)apply(e.newValue);});apply(lang);const obs=new root.MutationObserver(records=>records.forEach(r=>{if(r.type==='characterData'){if(r.target.parentElement&&!r.target.parentElement.closest('#planetLanguageToggle,input,textarea,select,script,style,code,pre,.lang-fa,.lang-en,[data-no-translate],.planet-ai-msg.user')){const v=transform(r.target.nodeValue,lang);if(v!==r.target.nodeValue)r.target.nodeValue=v;}}else if(r.type==='attributes'){const v=r.target.getAttribute(r.attributeName);if(v){const t=transform(v,lang);if(t!==v)r.target.setAttribute(r.attributeName,t);}}else r.addedNodes.forEach(n=>{if(n.nodeType===3){const v=transform(n.nodeValue,lang);if(v!==n.nodeValue)n.nodeValue=v;}else if(n.nodeType===1)translateTree(n,lang);});}));obs.observe(doc.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder','alt','value']});root.__planetLanguageObserver=obs;}root.PLANET_TRANSLATIONS=pairs;root.PlanetLanguage={transform,translateTree,initStandalone};})(window);
